package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.model.AccountType;
import com.mylosis.roster.ui.components.AccountTypeBadge;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * Builds the compact grid card layout for AccountCardPanel when grid view is enabled.
 * Text layout with a small 3-dot menu button in the top-right corner.
 */
public class GridAccountBuilder
{
    private GridAccountBuilder() {}

    public static final int GRID_CARD_HEIGHT = 56;

    public static void build(JPanel card, RosterPlugin plugin, Account profile, Runnable onEdit)
    {
        card.setLayout(new BorderLayout(0, 0));

        // Centered text with overlaid menu button in top-right
        JPanel content = new JPanel(new GridBagLayout());
        content.setOpaque(false);

        JPanel inner = new JPanel();
        inner.setLayout(new BoxLayout(inner, BoxLayout.Y_AXIS));
        inner.setOpaque(false);

        String displayName = AccountCardHelper.resolveDisplayName(profile, plugin.getConfig());

        // Name + clickable type badge, centered as a unit
        JPanel nameRow = new JPanel(new FlowLayout(FlowLayout.CENTER, Theme.SPACING_SM, 0));
        nameRow.setOpaque(false);
        nameRow.setAlignmentX(Component.CENTER_ALIGNMENT);

        JLabel nameLabel = AccountCardHelper.plainTextOnly(new JLabel(truncate(displayName, 12)));
        nameLabel.setForeground(Theme.TEXT_PRIMARY);
        nameLabel.setFont(Theme.fontBold(card.getFont(), Theme.FONT_SIZE_BODY));
        if (displayName.length() > 12) nameLabel.setToolTipText(AccountCardHelper.safeTooltip(displayName));
        nameRow.add(nameLabel);
        nameRow.add(createGridBadge(plugin, profile));
        inner.add(nameRow);

        String subtitle = getSubtitle(plugin, profile);
        if (subtitle != null)
        {
            inner.add(Box.createVerticalStrut(1));
            JLabel subLabel = AccountCardHelper.plainTextOnly(new JLabel(truncate(subtitle, 14)));
            subLabel.setForeground(Theme.TEXT_SECONDARY);
            subLabel.setFont(Theme.fontRegular(card.getFont(), Theme.FONT_SIZE_SMALL));
            subLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
            subLabel.setHorizontalAlignment(SwingConstants.CENTER);
            if (subtitle.length() > 14) subLabel.setToolTipText(AccountCardHelper.safeTooltip(subtitle));
            inner.add(subLabel);
        }

        content.add(inner);
        card.add(content, BorderLayout.CENTER);

        // 3-dot menu button on right, with matching spacer on left to keep text centered
        int btnSize = 16;
        JButton menuBtn = new JButton("\u22EE");
        menuBtn.setBackground(Theme.CARD_BACKGROUND);
        menuBtn.setForeground(Theme.TEXT_SECONDARY);
        menuBtn.setFocusPainted(false);
        menuBtn.setBorderPainted(false);
        menuBtn.setPreferredSize(new Dimension(btnSize, btnSize));
        menuBtn.setFont(menuBtn.getFont().deriveFont(12f));
        menuBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        menuBtn.setToolTipText("More options");

        AccountCardActions actions = new AccountCardActions(plugin, profile, onEdit);
        // Lazily built on first click — see AccountCardPanel.createMenuButton.
        JPopupMenu[] menuRef = new JPopupMenu[1];
        menuBtn.addActionListener(e -> {
            if (menuRef[0] == null)
            {
                menuRef[0] = actions.createContextMenu();
            }
            menuRef[0].show(menuBtn, 0, menuBtn.getHeight());
        });
        menuBtn.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e) { menuBtn.setBackground(Theme.CARD_HOVER); }

            @Override
            public void mouseExited(MouseEvent e) { menuBtn.setBackground(Theme.CARD_BACKGROUND); }
        });

        JPanel btnPanel = new JPanel(new GridBagLayout());
        btnPanel.setOpaque(false);
        btnPanel.setPreferredSize(new Dimension(btnSize + 4, 0));
        btnPanel.add(menuBtn);
        card.add(btnPanel, BorderLayout.EAST);

        // Matching spacer on left to balance the button width
        JPanel spacer = new JPanel();
        spacer.setOpaque(false);
        spacer.setPreferredSize(new Dimension(btnSize + 4, 0));
        card.add(spacer, BorderLayout.WEST);
    }

    private static AccountTypeBadge createGridBadge(RosterPlugin plugin, Account profile)
    {
        AccountType current = (profile.getMetadata() != null
            && profile.getMetadata().getAccountType() != null)
            ? profile.getMetadata().getAccountType()
            : AccountType.MAIN;
        // Slightly smaller than the list-view badge to fit the compact grid card
        return new AccountTypeBadge(current, 16, newType ->
        {
            AccountMetadata meta = profile.getMetadata();
            if (meta == null)
            {
                meta = AccountMetadata.createDefault();
                profile.setMetadata(meta);
            }
            meta.setAccountType(newType);
            plugin.getAccountStorage().saveAccount(profile);
            // Pre-Phase-A this relied on the ConfigChanged echo from the data write
            // to refresh the badge. That echo is now suppressed, so trigger explicitly.
            plugin.getPanel().rebuild();
        });
    }

    private static String getSubtitle(RosterPlugin plugin, Account profile)
    {
        boolean hideNotes = plugin.getConfig().hideNotes();
        boolean hideLogin = plugin.getConfig().hideLogin();
        boolean hideAlias = plugin.getConfig().hideAlias();
        boolean hideLastOnline = plugin.getConfig().hideLastOnline();

        if (!hideNotes && profile.getMetadata() != null && profile.getMetadata().getNotes() != null
            && !profile.getMetadata().getNotes().isEmpty())
        {
            return profile.getMetadata().getNotes();
        }
        if (!hideLogin && !hideAlias && profile.getUsername() != null
            && !profile.getUsername().equals(profile.getAlias()))
        {
            return profile.getUsername();
        }
        // Fall back to "X ago" when there's nothing more useful to show.
        if (!hideLastOnline && profile.getMetadata() != null
            && profile.getMetadata().getLastOnlineAt() != null)
        {
            return AccountCardHelper.formatTimeAgo(profile.getMetadata().getLastOnlineAt());
        }
        return null;
    }

    private static String truncate(String text, int maxChars)
    {
        if (text == null) return "";
        return text.length() > maxChars ? text.substring(0, maxChars) + "..." : text;
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.model.SortKey;
import com.mylosis.roster.ui.RosterPanel;
import com.mylosis.roster.ui.components.NotificationToast;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Executes drop operations for profiles and categories.
 * Handles moving profiles between categories and reordering.
 */
@Slf4j
public class DropExecutor
{
    private final RosterPlugin plugin;
    private final RosterPanel panel;

    public DropExecutor(RosterPlugin plugin, RosterPanel panel)
    {
        this.plugin = plugin;
        this.panel = panel;
    }

    /**
     * Perform a profile drop (move to category or reorder).
     *
     * <p>If a non-MANUAL sort key is active, dragging still records the new
     * {@code sortOrder} so the user's drag intent is preserved — but the visible
     * order won't change until they switch back to MANUAL. We surface a toast
     * the first time this happens so users aren't confused by "nothing happened".
     */
    public void executeProfileDrop(DragDropManager.DropTarget target, Account draggedAccount)
    {
        if (target.type != DragDropManager.DropTarget.Type.CATEGORY_DROP &&
            target.type != DragDropManager.DropTarget.Type.UNCATEGORIZED)
        {
            return;
        }

        String newGroupId = target.groupId;
        String currentGroupId = draggedAccount.getGroupId();
        int insertIndex = target.insertIndex;

        boolean isDifferentCategory = (currentGroupId == null && newGroupId != null) ||
            (currentGroupId != null && !currentGroupId.equals(newGroupId));

        if (isDifferentCategory)
        {
            moveProfileToCategory(draggedAccount, newGroupId, insertIndex);
        }
        else if (insertIndex >= 0)
        {
            reorderProfileInCategory(currentGroupId, draggedAccount, insertIndex);
            notifyIfSortOverridden();
            SwingUtilities.invokeLater(() -> panel.rebuild());
            log.debug("Reordered account {} to position {} in category {}",
                draggedAccount.getId(), insertIndex, currentGroupId);
        }
    }

    /**
     * If a non-MANUAL sort is active, the drag has updated {@code sortOrder} but the
     * visible position won't change. Tell the user once per session so the lack of
     * visible movement doesn't read as a broken drag.
     */
    private boolean shownSortOverrideHint = false;

    private void notifyIfSortOverridden()
    {
        if (shownSortOverrideHint)
        {
            return;
        }
        SortKey active = plugin.getConfig().sortKey();
        if (active == SortKey.MANUAL)
        {
            return;
        }
        shownSortOverrideHint = true;
        SwingUtilities.invokeLater(() ->
            panel.showNotification(
                "Drag order saved — switch to Manual sort to see it",
                NotificationToast.Type.INFO));
    }

    /**
     * Perform a category drop (reorder categories).
     */
    public void executeCategoryDrop(DragDropManager.DropTarget target, ProfileGroup draggedCategory)
    {
        if (target.type != DragDropManager.DropTarget.Type.CATEGORY_REORDER) return;

        List<ProfileGroup> groups = new ArrayList<>(plugin.getAccountStorage().getGroups());
        groups.sort((a, b) -> Integer.compare(a.getSortOrder(), b.getSortOrder()));

        int currentIndex = findGroupIndex(groups, draggedCategory.getId());
        if (currentIndex == -1) return;

        groups.remove(currentIndex);

        int insertIndex = target.insertIndex;
        if (currentIndex < insertIndex) insertIndex--;
        insertIndex = Math.max(0, Math.min(insertIndex, groups.size()));
        groups.add(insertIndex, draggedCategory);

        for (int i = 0; i < groups.size(); i++)
        {
            groups.get(i).setSortOrder(i);
        }
        // One batched save — per-group saveGroup() serialized the whole roster
        // into ConfigManager once per category, on the EDT.
        plugin.getAccountStorage().saveGroups(groups);

        SwingUtilities.invokeLater(() -> panel.rebuild());
        log.debug("Reordered category {} to position {}", draggedCategory.getName(), insertIndex);
    }

    private void moveProfileToCategory(Account profile, String newGroupId, int insertIndex)
    {
        profile.setGroupId(newGroupId);

        // Batch the moved account and every renumbered sibling into one save —
        // per-account saveAccount() serialized the whole roster into
        // ConfigManager once per account, making a drop O(n²) on the EDT.
        List<Account> siblings = getAccountsInCategory(newGroupId, profile.getId());
        siblings.sort(AccountData.SORT_ORDER_COMPARATOR);
        List<Account> changed = renumberWithInsert(siblings, profile, insertIndex);
        plugin.getAccountStorage().saveAccounts(changed);

        SwingUtilities.invokeLater(() -> panel.rebuild());
        log.debug("Moved account {} to category {} at position {}",
            profile.getId(), newGroupId, insertIndex);
    }

    private void reorderProfileInCategory(String groupId, Account profile, int newIndex)
    {
        List<Account> siblings = getAccountsInCategory(groupId, profile.getId());
        siblings.sort(AccountData.SORT_ORDER_COMPARATOR);
        List<Account> changed = renumberWithInsert(siblings, profile, newIndex);
        plugin.getAccountStorage().saveAccounts(changed);
    }

    /**
     * Inserts {@code moved} into {@code siblings} (sorted, not containing it) at
     * {@code insertIndex} and renumbers everyone's {@code sortOrder} sequentially.
     * A negative index means "no position information" (e.g. a drop on the
     * Uncategorized header) and appends: previously that case renumbered the
     * siblings but left the moved account's stale sortOrder untouched, so it
     * landed at an unpredictable position. Package-private and side-effect-only
     * on the passed accounts, so tests can exercise the ordering math directly.
     *
     * @return the accounts whose sortOrder was written, ready for a batched save.
     */
    static List<Account> renumberWithInsert(List<Account> siblings, Account moved, int insertIndex)
    {
        if (insertIndex < 0)
        {
            insertIndex = siblings.size();
        }
        insertIndex = Math.min(insertIndex, siblings.size());

        List<Account> ordered = new ArrayList<>(siblings);
        ordered.add(insertIndex, moved);

        List<Account> changed = new ArrayList<>(ordered.size());
        for (int i = 0; i < ordered.size(); i++)
        {
            Account p = ordered.get(i);
            // Null metadata is backfilled by AccountStorage.ensureSchema on load,
            // so this guard is belt-and-braces for accounts built in memory.
            if (p.getMetadata() != null)
            {
                p.getMetadata().setSortOrder(i);
                changed.add(p);
            }
            else if (p == moved)
            {
                // The moved account must always ride the batched save: a cross-
                // category move changes its groupId, and if the batch came back
                // empty the save would be skipped and the move lost on reload.
                changed.add(p);
            }
        }
        return changed;
    }

    private List<Account> getAccountsInCategory(String groupId, String excludeProfileId)
    {
        List<Account> result = new ArrayList<>();
        for (Account p : plugin.getAccountStorage().getAccounts())
        {
            String pGroupId = p.getGroupId();
            boolean sameCategory = (groupId == null && pGroupId == null) ||
                (groupId != null && groupId.equals(pGroupId));

            if (sameCategory && (excludeProfileId == null || !p.getId().equals(excludeProfileId)))
            {
                result.add(p);
            }
        }
        return result;
    }

    private int findGroupIndex(List<ProfileGroup> groups, String groupId)
    {
        for (int i = 0; i < groups.size(); i++)
        {
            if (groups.get(i).getId().equals(groupId)) return i;
        }
        return -1;
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import java.awt.*;
import java.awt.geom.RoundRectangle2D;

/**
 * Overlay component that shows drag feedback - a ghost of the dragged item
 * following the mouse cursor, and highlighting of valid drop targets.
 */
public class DragOverlay extends JComponent
{
    private final DragDropManager dragManager;

    private Point mouseLocation = null;
    private Image dragImage = null;
    private int dragImageWidth = 0;
    private int dragImageHeight = 0;

    // Strokes are immutable — allocate once instead of every paintComponent.
    // At ~60Hz during a drag, the previous code created six BasicStroke objects
    // per frame for tiny ornaments that never change.
    private static final BasicStroke STROKE_GHOST_BORDER = new BasicStroke(2);
    private static final BasicStroke STROKE_DROP_DASHED = new BasicStroke(
        2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 0, new float[]{6, 4}, 0);
    private static final BasicStroke STROKE_CATEGORY_REORDER = new BasicStroke(3);
    private static final BasicStroke STROKE_INSERT_LINE = new BasicStroke(2);
    private static final BasicStroke STROKE_FALLBACK_ARROW = new BasicStroke(
        2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

    // Same story for the colors and the ghost composite — all constant, all
    // previously allocated per frame. AWT only caches AlphaComposite instances
    // for alpha == 1.0, so the 0.85f ghost composite is worth holding onto.
    private static final Color GHOST_SHADOW = new Color(0, 0, 0, 30);
    private static final Color HIGHLIGHT_FILL = new Color(Theme.BUTTON_PRIMARY.getRed(),
        Theme.BUTTON_PRIMARY.getGreen(), Theme.BUTTON_PRIMARY.getBlue(), 40);
    private static final Color INDICATOR_FILL = new Color(Theme.BUTTON_PRIMARY.getRed(),
        Theme.BUTTON_PRIMARY.getGreen(), Theme.BUTTON_PRIMARY.getBlue(), 100);
    private static final AlphaComposite GHOST_COMPOSITE =
        AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.85f);

    public DragOverlay(DragDropManager dragManager)
    {
        this.dragManager = dragManager;
        setOpaque(false);
    }

    public void setMouseLocation(Point screenPoint)
    {
        if (screenPoint != null && getParent() != null)
        {
            try
            {
                Point parentLocation = getParent().getLocationOnScreen();
                this.mouseLocation = new Point(
                    screenPoint.x - parentLocation.x,
                    screenPoint.y - parentLocation.y
                );
            }
            catch (IllegalComponentStateException e)
            {
                // Parent no longer showing (panel closed mid-drag)
                this.mouseLocation = null;
            }
        }
        else
        {
            this.mouseLocation = null;
        }
        repaint();
    }

    public void setDragImage(Component source)
    {
        if (source != null && source.getWidth() > 0 && source.getHeight() > 0)
        {
            dragImageWidth = Math.min(source.getWidth(), 250);
            dragImageHeight = Math.min(source.getHeight(), 80);

            // Create image from component
            dragImage = new java.awt.image.BufferedImage(
                dragImageWidth, dragImageHeight,
                java.awt.image.BufferedImage.TYPE_INT_ARGB
            );
            Graphics2D g2d = (Graphics2D) dragImage.getGraphics();
            g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            // Scale if needed
            double scaleX = (double) dragImageWidth / source.getWidth();
            double scaleY = (double) dragImageHeight / source.getHeight();
            double scale = Math.min(scaleX, scaleY);

            g2d.scale(scale, scale);
            source.paint(g2d);
            g2d.dispose();
        }
        else
        {
            dragImage = null;
        }
    }

    public void clearDragImage()
    {
        dragImage = null;
        mouseLocation = null;
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        if (!dragManager.isDragging())
        {
            return;
        }

        Graphics2D g2d = (Graphics2D) g.create();
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        // Draw drop target highlight
        DragDropManager.DropTarget target = dragManager.getCurrentDropTarget();
        if (target != null)
        {
            drawDropTargetHighlight(g2d, target);
        }

        // Draw drag ghost at mouse position
        if (mouseLocation != null && dragImage != null)
        {
            int x = mouseLocation.x - dragImageWidth / 2;
            int y = mouseLocation.y - dragImageHeight / 2;

            // Draw shadow
            g2d.setColor(GHOST_SHADOW);
            g2d.fillRoundRect(x + 4, y + 4, dragImageWidth, dragImageHeight, 8, 8);

            // Draw semi-transparent image
            g2d.setComposite(GHOST_COMPOSITE);
            g2d.drawImage(dragImage, x, y, null);

            // Draw border
            g2d.setComposite(AlphaComposite.SrcOver);
            g2d.setColor(Theme.BUTTON_PRIMARY);
            g2d.setStroke(STROKE_GHOST_BORDER);
            g2d.drawRoundRect(x, y, dragImageWidth - 1, dragImageHeight - 1, 8, 8);
        }
        else if (mouseLocation != null)
        {
            // Fallback: draw a simple indicator if no image
            drawDragIndicator(g2d);
        }

        g2d.dispose();
    }

    private void drawDropTargetHighlight(Graphics2D g2d, DragDropManager.DropTarget target)
    {
        try
        {
            // Convert target bounds from screen to local coordinates
            Rectangle bounds = target.bounds;
            Point parentScreen = getParent().getLocationOnScreen();

            int x = bounds.x - parentScreen.x;
            int y = bounds.y - parentScreen.y;
            int width = bounds.width;
            int height = bounds.height;

            // Draw highlight background
            g2d.setColor(HIGHLIGHT_FILL);
            g2d.fillRoundRect(x, y, width, height, 6, 6);

            // Draw highlight border
            g2d.setColor(Theme.BUTTON_PRIMARY);
            g2d.setStroke(STROKE_DROP_DASHED);
            g2d.drawRoundRect(x + 1, y + 1, width - 2, height - 2, 6, 6);

            // Draw "drop here" indicator for category reordering or profile positioning
            if (target.type == DragDropManager.DropTarget.Type.CATEGORY_REORDER)
            {
                g2d.setStroke(STROKE_CATEGORY_REORDER);
                g2d.setColor(Theme.BUTTON_PRIMARY);

                // Draw line at insert position
                int lineY = (target.insertIndex <= 0) ? y : y + height;
                g2d.drawLine(x + 10, lineY, x + width - 10, lineY);

                // Draw arrow heads
                int arrowSize = 6;
                g2d.fillPolygon(
                    new int[]{x + 10, x + 10 + arrowSize, x + 10},
                    new int[]{lineY - arrowSize, lineY, lineY + arrowSize},
                    3
                );
                g2d.fillPolygon(
                    new int[]{x + width - 10, x + width - 10 - arrowSize, x + width - 10},
                    new int[]{lineY - arrowSize, lineY, lineY + arrowSize},
                    3
                );
            }
            else if ((target.type == DragDropManager.DropTarget.Type.CATEGORY_DROP
                || target.type == DragDropManager.DropTarget.Type.UNCATEGORIZED)
                && target.insertIndex >= 0)
            {
                // Draw insert position indicator for profile drops
                g2d.setStroke(STROKE_INSERT_LINE);
                g2d.setColor(Theme.BUTTON_PRIMARY);

                // Draw a small "insert here" line
                int lineX = x + 20;
                int lineWidth = width - 40;

                // Exact position measured from real card bounds by DropTargetFinder;
                // the geometric estimate remains only as the empty-category fallback.
                int insertY = target.insertLineY >= 0
                    ? target.insertLineY - parentScreen.y
                    : y + 45 + (target.insertIndex * 75);
                insertY = Math.max(y + 5, Math.min(insertY, y + height - 5));

                g2d.drawLine(lineX, insertY, lineX + lineWidth, insertY);

                // Draw small triangles
                int arrowSize = 5;
                g2d.fillPolygon(
                    new int[]{lineX, lineX + arrowSize, lineX},
                    new int[]{insertY - arrowSize, insertY, insertY + arrowSize},
                    3
                );
                g2d.fillPolygon(
                    new int[]{lineX + lineWidth, lineX + lineWidth - arrowSize, lineX + lineWidth},
                    new int[]{insertY - arrowSize, insertY, insertY + arrowSize},
                    3
                );
            }
        }
        catch (Exception e)
        {
            // Component might not be showing
        }
    }

    private void drawDragIndicator(Graphics2D g2d)
    {
        // Simple fallback indicator
        int size = 40;
        int x = mouseLocation.x - size / 2;
        int y = mouseLocation.y - size / 2;

        g2d.setColor(INDICATOR_FILL);
        g2d.fillOval(x, y, size, size);

        g2d.setColor(Theme.BUTTON_PRIMARY);
        g2d.setStroke(STROKE_GHOST_BORDER);
        g2d.drawOval(x, y, size, size);

        // Draw move icon
        g2d.setColor(Theme.TEXT_PRIMARY);
        int cx = mouseLocation.x;
        int cy = mouseLocation.y;
        int arrowLen = 8;

        // Four arrows pointing outward
        g2d.setStroke(STROKE_FALLBACK_ARROW);
        g2d.drawLine(cx, cy - arrowLen, cx, cy + arrowLen);
        g2d.drawLine(cx - arrowLen, cy, cx + arrowLen, cy);
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.ui.CategoryPanel;
import com.mylosis.roster.ui.AccountCardPanel;
import com.mylosis.roster.ui.RosterPanel;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Finds drop targets for drag-and-drop operations by walking the component tree.
 */
@Slf4j
public class DropTargetFinder
{
    private final RosterPanel panel;

    // Per-drag snapshot of the panel structure. Populated by primeSnapshot() at
    // drag start, consulted on every mouse-moved event (~60Hz). The previous
    // implementation walked the entire component tree on every single event —
    // for a panel with ~50 components that's ~3000 traversals per second of dragging.
    private List<CategoryPanel> snapshotCategoryPanels;
    private JPanel snapshotUncategorizedHeader;
    private JPanel snapshotUncategorizedContainer;
    private List<AccountCardPanel> snapshotUncategorizedCards;
    // Cards per category, walked once at drag start. calculateInsertPoint runs
    // on every mouse-moved event while hovering a category; without this it
    // re-walked the category's whole component subtree each event.
    private java.util.Map<CategoryPanel, List<AccountCardPanel>> snapshotCardsByCategory;

    public DropTargetFinder(RosterPanel panel)
    {
        this.panel = panel;
    }

    /**
     * Snapshot the panel's drop-target component structure for the lifetime of a
     * single drag. Called by {@link DragDropManager#startProfileDrag} and
     * {@link DragDropManager#startCategoryDrag}; cleared by {@code resetDragState}.
     * The snapshot is invalidated if the panel rebuilds during the drag — but the
     * drag itself will end on mouse release, so a stale snapshot at worst causes
     * one final frame of imprecise highlighting.
     */
    public void primeSnapshot()
    {
        snapshotCategoryPanels = findCategoryPanels();
        snapshotUncategorizedHeader = findPanelWithProperty("UNCATEGORIZED_HEADER");
        snapshotUncategorizedContainer = findPanelWithProperty("UNCATEGORIZED_CONTAINER");
        snapshotUncategorizedCards = new ArrayList<>();
        if (snapshotUncategorizedContainer != null)
        {
            findProfileCards(snapshotUncategorizedContainer, snapshotUncategorizedCards);
        }
        snapshotCardsByCategory = new java.util.HashMap<>();
        for (CategoryPanel categoryPanel : snapshotCategoryPanels)
        {
            List<AccountCardPanel> cards = new ArrayList<>();
            findProfileCards(categoryPanel, cards);
            snapshotCardsByCategory.put(categoryPanel, cards);
        }
    }

    /**
     * Drop the per-drag snapshot. Called by {@code DragDropManager.resetDragState}.
     */
    public void clearSnapshot()
    {
        snapshotCategoryPanels = null;
        snapshotUncategorizedHeader = null;
        snapshotUncategorizedContainer = null;
        snapshotUncategorizedCards = null;
        snapshotCardsByCategory = null;
    }

    /**
     * Find the drop target at the given screen point for a profile drag.
     */
    public DragDropManager.DropTarget findForProfile(Point screenPoint, Account draggedAccount)
    {
        DragDropManager.DropTarget target = checkCategoryPanels(screenPoint, draggedAccount);
        if (target != null)
        {
            return target;
        }
        return checkUncategorizedArea(screenPoint);
    }

    /**
     * Find the drop target at the given screen point for a category drag.
     */
    public DragDropManager.DropTarget findForCategory(Point screenPoint, ProfileGroup draggedCategory)
    {
        List<CategoryPanel> categoryPanels = snapshotCategoryPanels != null
            ? snapshotCategoryPanels
            : findCategoryPanels();

        for (int i = 0; i < categoryPanels.size(); i++)
        {
            CategoryPanel categoryPanel = categoryPanels.get(i);
            if (!categoryPanel.isShowing()) continue;
            if (draggedCategory != null &&
                categoryPanel.getGroup().getId().equals(draggedCategory.getId()))
            {
                continue;
            }

            try
            {
                Point panelLocation = categoryPanel.getLocationOnScreen();
                int headerHeight = categoryPanel.getHeaderHeight();
                Rectangle headerBounds = new Rectangle(
                    panelLocation.x, panelLocation.y,
                    categoryPanel.getWidth(), headerHeight > 0 ? headerHeight : 45
                );

                if (headerBounds.contains(screenPoint))
                {
                    int midY = headerBounds.y + headerBounds.height / 2;
                    int insertIndex = screenPoint.y < midY ? i : i + 1;
                    return new DragDropManager.DropTarget(
                        DragDropManager.DropTarget.Type.CATEGORY_REORDER,
                        categoryPanel.getGroup().getId(),
                        headerBounds, insertIndex
                    );
                }
            }
            catch (Exception e)
            {
                // Component might not be showing
            }
        }
        return null;
    }

    private DragDropManager.DropTarget checkCategoryPanels(Point screenPoint, Account draggedAccount)
    {
        List<CategoryPanel> categoryPanels = snapshotCategoryPanels != null
            ? snapshotCategoryPanels
            : findCategoryPanels();

        for (CategoryPanel categoryPanel : categoryPanels)
        {
            if (!categoryPanel.isShowing()) continue;

            try
            {
                Point panelLocation = categoryPanel.getLocationOnScreen();
                Rectangle panelBounds = new Rectangle(
                    panelLocation.x, panelLocation.y,
                    categoryPanel.getWidth(), categoryPanel.getHeight()
                );

                if (panelBounds.contains(screenPoint))
                {
                    String groupId = categoryPanel.getGroup().getId();
                    InsertPoint insert = calculateInsertPoint(categoryPanel, screenPoint);
                    return new DragDropManager.DropTarget(
                        DragDropManager.DropTarget.Type.CATEGORY_DROP,
                        groupId, panelBounds, insert.index, insert.lineY
                    );
                }
            }
            catch (Exception e)
            {
                // Component might not be showing
            }
        }
        return null;
    }

    /**
     * Hit-tests the whole uncategorized region: the "Uncategorized" header (when
     * groups exist) plus the ungrouped card list below it. Previously only the
     * header was a target, so drops "into Uncategorized" felt broken next to
     * real categories (whose entire panel accepts drops), and reordering within
     * Uncategorized was impossible. Insert position comes from the real card
     * bounds, exactly like {@link #calculateInsertPoint}.
     */
    private DragDropManager.DropTarget checkUncategorizedArea(Point screenPoint)
    {
        JPanel header = snapshotUncategorizedHeader != null
            ? snapshotUncategorizedHeader
            : findPanelWithProperty("UNCATEGORIZED_HEADER");
        JPanel container = snapshotUncategorizedContainer != null
            ? snapshotUncategorizedContainer
            : findPanelWithProperty("UNCATEGORIZED_CONTAINER");

        Rectangle area = null;
        area = unionShowingBounds(area, header);
        area = unionShowingBounds(area, container);
        if (area == null || !area.contains(screenPoint))
        {
            return null;
        }

        List<AccountCardPanel> cards = snapshotUncategorizedCards;
        if (cards == null)
        {
            cards = new ArrayList<>();
            if (container != null)
            {
                findProfileCards(container, cards);
            }
        }
        InsertPoint insert = insertPointFromCards(cards, screenPoint);
        return new DragDropManager.DropTarget(
            DragDropManager.DropTarget.Type.UNCATEGORIZED, null, area,
            insert.index, insert.lineY
        );
    }

    /** Extends {@code area} to cover {@code panel}'s on-screen bounds; returns
     *  the (possibly new) rectangle, or {@code area} unchanged if the panel is
     *  null or not showing. */
    private static Rectangle unionShowingBounds(Rectangle area, JPanel panel)
    {
        if (panel == null || !panel.isShowing())
        {
            return area;
        }
        try
        {
            Point location = panel.getLocationOnScreen();
            Rectangle bounds = new Rectangle(location.x, location.y, panel.getWidth(), panel.getHeight());
            return area == null ? bounds : area.union(bounds);
        }
        catch (Exception e)
        {
            // Component might not be showing
            return area;
        }
    }

    /**
     * Insert position within a category: the index the dragged card would land
     * at, plus the exact screen-Y where the insert line should be drawn. The
     * line Y comes from the real card bounds; the overlay used to estimate it
     * from an assumed 75px card height, which drifted whenever cards varied
     * (notes line, last-online line, grid mode).
     */
    static final class InsertPoint
    {
        final int index;
        /** Screen Y for the indicator line; -1 when unknown (empty category). */
        final int lineY;

        InsertPoint(int index, int lineY)
        {
            this.index = index;
            this.lineY = lineY;
        }
    }

    InsertPoint calculateInsertPoint(CategoryPanel categoryPanel, Point screenPoint)
    {
        List<AccountCardPanel> cards = snapshotCardsByCategory != null
            ? snapshotCardsByCategory.get(categoryPanel)
            : null;
        if (cards == null)
        {
            cards = new ArrayList<>();
            findProfileCards(categoryPanel, cards);
        }
        return insertPointFromCards(cards, screenPoint);
    }

    static InsertPoint insertPointFromCards(List<AccountCardPanel> cards, Point screenPoint)
    {
        if (cards == null || cards.isEmpty()) return new InsertPoint(0, -1);

        int lastVisibleBottom = -1;
        for (int i = 0; i < cards.size(); i++)
        {
            AccountCardPanel card = cards.get(i);
            if (!card.isShowing()) continue;

            try
            {
                Point cardLocation = card.getLocationOnScreen();
                int cardMidY = cardLocation.y + card.getHeight() / 2;
                if (screenPoint.y < cardMidY)
                {
                    return new InsertPoint(i, cardLocation.y);
                }
                lastVisibleBottom = cardLocation.y + card.getHeight();
            }
            catch (Exception e)
            {
                // Component might not be showing
            }
        }
        return new InsertPoint(cards.size(), lastVisibleBottom);
    }

    private void findProfileCards(Container container, List<AccountCardPanel> result)
    {
        for (Component comp : container.getComponents())
        {
            if (comp instanceof AccountCardPanel)
            {
                result.add((AccountCardPanel) comp);
            }
            if (comp instanceof Container)
            {
                findProfileCards((Container) comp, result);
            }
        }
    }

    List<CategoryPanel> findCategoryPanels()
    {
        List<CategoryPanel> result = new ArrayList<>();
        findCategoryPanelsRecursive(panel, result);
        return result;
    }

    private void findCategoryPanelsRecursive(Container container, List<CategoryPanel> result)
    {
        if (container instanceof JScrollPane)
        {
            JScrollPane scrollPane = (JScrollPane) container;
            Component view = scrollPane.getViewport().getView();
            if (view instanceof CategoryPanel) result.add((CategoryPanel) view);
            if (view instanceof Container) findCategoryPanelsRecursive((Container) view, result);
            return;
        }

        for (Component comp : container.getComponents())
        {
            if (comp instanceof CategoryPanel) result.add((CategoryPanel) comp);
            if (comp instanceof Container) findCategoryPanelsRecursive((Container) comp, result);
        }
    }

    /** Finds the first JPanel in the tree tagged with the given client property
     *  set to {@code Boolean.TRUE} (e.g. "UNCATEGORIZED_HEADER" or
     *  "UNCATEGORIZED_CONTAINER", tagged by AccountListBuilder). */
    private JPanel findPanelWithProperty(String propertyKey)
    {
        List<JPanel> result = new ArrayList<>();
        findPanelWithPropertyRecursive(panel, propertyKey, result);
        return result.isEmpty() ? null : result.get(0);
    }

    private void findPanelWithPropertyRecursive(Container container, String propertyKey, List<JPanel> result)
    {
        if (!result.isEmpty()) return;

        if (container instanceof JScrollPane)
        {
            JScrollPane scrollPane = (JScrollPane) container;
            Component view = scrollPane.getViewport().getView();
            if (view instanceof JPanel && Boolean.TRUE.equals(((JPanel) view).getClientProperty(propertyKey)))
            {
                result.add((JPanel) view);
                return;
            }
            if (view instanceof Container) findPanelWithPropertyRecursive((Container) view, propertyKey, result);
            return;
        }

        for (Component comp : container.getComponents())
        {
            if (comp instanceof JPanel && Boolean.TRUE.equals(((JPanel) comp).getClientProperty(propertyKey)))
            {
                result.add((JPanel) comp);
                return;
            }
            if (comp instanceof Container) findPanelWithPropertyRecursive((Container) comp, propertyKey, result);
        }
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.model.ProfileGroup;

import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * Mouse listener for dragging categories to reorder them.
 */
public class CategoryDragListener extends MouseAdapter
{
    private final DragDropManager dragManager;
    private final ProfileGroup category;

    private Point pressPoint = null;
    private boolean dragStarted = false;

    private static final int DRAG_THRESHOLD = 10;

    public CategoryDragListener(DragDropManager dragManager, ProfileGroup category)
    {
        this.dragManager = dragManager;
        this.category = category;
    }

    @Override
    public void mousePressed(MouseEvent e)
    {
        if (e.getButton() == MouseEvent.BUTTON1)
        {
            pressPoint = e.getLocationOnScreen();
            dragStarted = false;
        }
    }

    @Override
    public void mouseReleased(MouseEvent e)
    {
        if (dragStarted)
        {
            dragManager.endDrag(e.getLocationOnScreen());
        }
        pressPoint = null;
        dragStarted = false;
    }

    @Override
    public void mouseDragged(MouseEvent e)
    {
        if (pressPoint == null) return;

        Point current = e.getLocationOnScreen();

        if (!dragStarted)
        {
            int dx = Math.abs(current.x - pressPoint.x);
            int dy = Math.abs(current.y - pressPoint.y);

            if (dx > DRAG_THRESHOLD || dy > DRAG_THRESHOLD)
            {
                dragStarted = true;
                dragManager.startCategoryDrag(category, e.getComponent(), pressPoint);
            }
        }

        if (dragStarted)
        {
            dragManager.updateDrag(current);
        }
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.model.Account;
import com.mylosis.roster.ui.AccountCardPanel;

import javax.swing.*;
import java.awt.Component;
import java.awt.Container;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * Mouse listener for dragging profiles between categories.
 * Attaches to a AccountCardPanel and all its children to ensure drag works from anywhere on the card.
 * Also handles click detection to trigger profile selection and edit.
 */
public class AccountDragListener extends MouseAdapter
{
    private final DragDropManager dragManager;
    private final Account profile;
    private final AccountCardPanel card;

    private Point pressPoint = null;
    private long pressTime = 0;
    private boolean dragStarted = false;
    private static long lastClickTime = 0;
    // Track the account by id, not by reference: a static Account would pin
    // the object graph across panel rebuilds and plugin restarts, and rebuilds
    // may replace the instance, silently breaking double-click detection.
    private static String lastClickAccountId = null;

    private static final int DRAG_THRESHOLD = 10;
    private static final int CLICK_TIME_THRESHOLD = 300;
    private static final int DOUBLE_CLICK_THRESHOLD = 400;

    public AccountDragListener(DragDropManager dragManager, Account profile, AccountCardPanel card)
    {
        this.dragManager = dragManager;
        this.profile = profile;
        this.card = card;
    }

    /**
     * Attach this listener to the card and all its children recursively.
     */
    public void attachToComponent(Component component)
    {
        component.addMouseListener(this);
        component.addMouseMotionListener(this);

        if (component instanceof Container)
        {
            for (Component child : ((Container) component).getComponents())
            {
                // Don't attach to buttons (let them handle their own clicks)
                if (!(child instanceof JButton))
                {
                    attachToComponent(child);
                }
            }
        }
    }

    @Override
    public void mousePressed(MouseEvent e)
    {
        if (e.getButton() == MouseEvent.BUTTON1 && !card.isExpanded())
        {
            pressPoint = e.getLocationOnScreen();
            pressTime = System.currentTimeMillis();
            dragStarted = false;
        }
    }

    @Override
    public void mouseReleased(MouseEvent e)
    {
        if (e.getButton() != MouseEvent.BUTTON1)
        {
            return;
        }

        if (dragStarted)
        {
            dragManager.endDrag(e.getLocationOnScreen());
        }
        else if (pressPoint != null)
        {
            // This was a click, not a drag - handle it
            long duration = System.currentTimeMillis() - pressTime;
            Point current = e.getLocationOnScreen();
            int dx = Math.abs(current.x - pressPoint.x);
            int dy = Math.abs(current.y - pressPoint.y);

            if (duration < CLICK_TIME_THRESHOLD && dx < DRAG_THRESHOLD && dy < DRAG_THRESHOLD)
            {
                // Check for double-click
                long now = System.currentTimeMillis();
                if (profile.getId() != null && profile.getId().equals(lastClickAccountId)
                    && (now - lastClickTime) < DOUBLE_CLICK_THRESHOLD)
                {
                    // Double-click: expand card for inline editing
                    SwingUtilities.invokeLater(() -> card.expand());
                    lastClickTime = 0;
                    lastClickAccountId = null;
                }
                else
                {
                    // Single-click: select profile (only if card not expanded)
                    lastClickTime = now;
                    lastClickAccountId = profile.getId();
                    if (!card.isExpanded())
                    {
                        dragManager.getPlugin().selectAccount(profile);
                    }
                }
            }
        }

        pressPoint = null;
        dragStarted = false;
    }

    @Override
    public void mouseDragged(MouseEvent e)
    {
        if (pressPoint == null) return;

        Point current = e.getLocationOnScreen();

        if (!dragStarted)
        {
            int dx = Math.abs(current.x - pressPoint.x);
            int dy = Math.abs(current.y - pressPoint.y);

            if (dx > DRAG_THRESHOLD || dy > DRAG_THRESHOLD)
            {
                dragStarted = true;
                dragManager.startProfileDrag(profile, card, pressPoint);
            }
        }

        if (dragStarted)
        {
            dragManager.updateDrag(current);
        }
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.ui.RosterPanel;
import lombok.extern.slf4j.Slf4j;

import java.awt.*;
import java.awt.event.AWTEventListener;
import java.awt.event.KeyEvent;

/**
 * Manages drag and drop for profiles and categories.
 * Delegates drop target finding to DropTargetFinder and drop execution to DropExecutor.
 */
@Slf4j
public class DragDropManager
{
    private final RosterPlugin plugin;
    private final DragOverlay overlay;
    private final DropTargetFinder targetFinder;
    private final DropExecutor dropExecutor;

    // Drag state
    private boolean isDragging = false;
    private DragType dragType = null;
    private Account draggedAccount = null;
    private ProfileGroup draggedCategory = null;
    private Component dragSource = null;
    private Point dragStartPoint = null;
    private Point currentDragPoint = null;
    private DropTarget currentDropTarget = null;

    /**
     * ESC aborts an in-flight drag. A Toolkit-level listener (registered only for
     * the drag's duration, same pattern as ExpandingMenuButton's dismissal) rather
     * than a Swing key binding: during a drag, focus may sit on the game's
     * heavyweight Canvas, where WHEN_IN_FOCUSED_WINDOW bindings never fire.
     */
    private final AWTEventListener escapeListener = event -> {
        if (isDragging && event instanceof KeyEvent)
        {
            KeyEvent ke = (KeyEvent) event;
            if (ke.getID() == KeyEvent.KEY_PRESSED && ke.getKeyCode() == KeyEvent.VK_ESCAPE)
            {
                ke.consume();
                cancelDrag();
            }
        }
    };

    public enum DragType
    {
        PROFILE,
        CATEGORY
    }

    public static class DropTarget
    {
        public enum Type { CATEGORY_DROP, UNCATEGORIZED, CATEGORY_REORDER }

        public final Type type;
        public final String groupId;
        public final Rectangle bounds;
        public final int insertIndex;
        /** Exact screen-Y of the insert indicator line, measured from the real
         *  card bounds in the drag snapshot. -1 when unknown (empty category),
         *  in which case the overlay falls back to its geometric estimate. */
        public final int insertLineY;

        public DropTarget(Type type, String groupId, Rectangle bounds)
        {
            this(type, groupId, bounds, -1);
        }

        public DropTarget(Type type, String groupId, Rectangle bounds, int insertIndex)
        {
            this(type, groupId, bounds, insertIndex, -1);
        }

        public DropTarget(Type type, String groupId, Rectangle bounds, int insertIndex, int insertLineY)
        {
            this.type = type;
            this.groupId = groupId;
            this.bounds = bounds;
            this.insertIndex = insertIndex;
            this.insertLineY = insertLineY;
        }
    }

    public DragDropManager(RosterPlugin plugin, RosterPanel panel)
    {
        this.plugin = plugin;
        this.overlay = new DragOverlay(this);
        this.targetFinder = new DropTargetFinder(panel);
        this.dropExecutor = new DropExecutor(plugin, panel);
    }

    public DragOverlay getOverlay()
    {
        return overlay;
    }

    public RosterPlugin getPlugin()
    {
        return plugin;
    }

    public void startProfileDrag(Account profile, Component source, Point screenPoint)
    {
        if (isDragging) return;
        isDragging = true;
        dragType = DragType.PROFILE;
        draggedAccount = profile;
        dragSource = source;
        dragStartPoint = screenPoint;
        currentDragPoint = screenPoint;
        // Snapshot the panel structure once per drag so updateDrag() doesn't
        // re-walk the component tree on every mouse-moved event.
        targetFinder.primeSnapshot();
        overlay.setDragImage(source);
        overlay.setMouseLocation(screenPoint);
        overlay.setVisible(true);
        Toolkit.getDefaultToolkit().addAWTEventListener(escapeListener, AWTEvent.KEY_EVENT_MASK);
        log.debug("Started dragging account: {}", profile.getId());
    }

    public void startCategoryDrag(ProfileGroup category, Component source, Point screenPoint)
    {
        if (isDragging) return;
        isDragging = true;
        dragType = DragType.CATEGORY;
        draggedCategory = category;
        dragSource = source;
        dragStartPoint = screenPoint;
        currentDragPoint = screenPoint;
        targetFinder.primeSnapshot();
        overlay.setDragImage(source);
        overlay.setMouseLocation(screenPoint);
        overlay.setVisible(true);
        Toolkit.getDefaultToolkit().addAWTEventListener(escapeListener, AWTEvent.KEY_EVENT_MASK);
        log.debug("Started dragging category: {}", category.getName());
    }

    public void updateDrag(Point screenPoint)
    {
        if (!isDragging) return;
        currentDragPoint = screenPoint;
        currentDropTarget = findDropTarget(screenPoint);
        // setMouseLocation already repaints the overlay.
        overlay.setMouseLocation(screenPoint);
    }

    public void endDrag(Point screenPoint)
    {
        if (!isDragging) return;
        currentDragPoint = screenPoint;
        DropTarget target = findDropTarget(screenPoint);

        if (target != null)
        {
            performDrop(target);
        }

        resetDragState();
    }

    public void cancelDrag()
    {
        resetDragState();
    }

    public boolean isDragging()
    {
        return isDragging;
    }

    public DropTarget getCurrentDropTarget()
    {
        return currentDropTarget;
    }

    public Account getDraggedProfile()
    {
        return draggedAccount;
    }

    public ProfileGroup getDraggedCategory()
    {
        return draggedCategory;
    }

    private DropTarget findDropTarget(Point screenPoint)
    {
        if (dragType == DragType.PROFILE)
        {
            return targetFinder.findForProfile(screenPoint, draggedAccount);
        }
        else if (dragType == DragType.CATEGORY)
        {
            return targetFinder.findForCategory(screenPoint, draggedCategory);
        }
        return null;
    }

    private void performDrop(DropTarget target)
    {
        if (dragType == DragType.PROFILE && draggedAccount != null)
        {
            dropExecutor.executeProfileDrop(target, draggedAccount);
        }
        else if (dragType == DragType.CATEGORY && draggedCategory != null)
        {
            dropExecutor.executeCategoryDrop(target, draggedCategory);
        }
    }

    private void resetDragState()
    {
        // Removing a listener that was never added is a documented no-op, so
        // this is safe on every reset path (drop, cancel, ESC).
        Toolkit.getDefaultToolkit().removeAWTEventListener(escapeListener);
        isDragging = false;
        dragType = null;
        draggedAccount = null;
        draggedCategory = null;
        dragSource = null;
        dragStartPoint = null;
        currentDragPoint = null;
        currentDropTarget = null;
        targetFinder.clearSnapshot();
        overlay.clearDragImage();
        overlay.setVisible(false);
        overlay.repaint();
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.ui.components.InlineAccountForm;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

/**
 * Handles the inline add-profile form within a CategoryPanel.
 * Also handles category rename and delete actions.
 */
public class CategoryFormHandler
{
    private final RosterPlugin plugin;
    private final ProfileGroup group;
    private final Runnable onToggleCollapsed;

    private JPanel addFormPanel;
    private InlineAccountForm addForm;
    private boolean addFormVisible = false;

    public CategoryFormHandler(RosterPlugin plugin, ProfileGroup group, Runnable onToggleCollapsed)
    {
        this.plugin = plugin;
        this.group = group;
        this.onToggleCollapsed = onToggleCollapsed;
    }

    public JPanel getOrCreateFormPanel()
    {
        if (addFormPanel == null)
        {
            addFormPanel = buildFormPanel();
        }
        return addFormPanel;
    }

    public void toggleAddForm(boolean isCollapsed, Component parent)
    {
        addFormVisible = !addFormVisible;
        if (addFormVisible)
        {
            ensureAddForm();
        }
        addFormPanel.setVisible(addFormVisible);

        if (addFormVisible)
        {
            if (isCollapsed) onToggleCollapsed.run();
            addForm.focusUsernameField();
        }

        parent.revalidate();
        ((JComponent) parent).repaint();
    }

    public JPopupMenu createContextMenu()
    {
        JPopupMenu menu = new JPopupMenu();

        JMenuItem renameItem = new JMenuItem("Rename");
        renameItem.addActionListener(e -> renameCategory());
        menu.add(renameItem);

        JMenuItem addAccountItem = new JMenuItem("Add Account");
        addAccountItem.addActionListener(e ->
            toggleAddForm(false, plugin.getPanel()));
        menu.add(addAccountItem);

        menu.addSeparator();
        JMenu colorMenu = new JMenu("Set Color");
            for (int i = 0; i < Theme.CATEGORY_COLORS.length; i++)
            {
                JMenuItem swatch = createColorSwatch(Theme.CATEGORY_COLORS[i], Theme.CATEGORY_COLOR_NAMES[i]);
                colorMenu.add(swatch);
            }
            colorMenu.addSeparator();
            JMenuItem customColor = new JMenuItem("Custom...");
            customColor.addActionListener(e ->
            {
                Color current = Theme.parseColor(group.getColor());
                net.runelite.client.ui.components.colorpicker.RuneliteColorPicker picker =
                    plugin.getColorPickerManager().create(
                        SwingUtilities.getWindowAncestor(plugin.getPanel()),
                        current != null ? current : Theme.ACCENT_ORANGE,
                        group.getName() + " Color",
                        true // hide alpha slider
                    );
                picker.setOnClose(chosen -> {
                    group.setColor(Theme.colorToHex(chosen));
                    plugin.getAccountStorage().saveGroup(group);
                    plugin.getPanel().rebuild();
                });
                picker.setVisible(true);
            });
            colorMenu.add(customColor);
            JMenuItem resetColor = new JMenuItem("Reset Color");
            resetColor.addActionListener(e -> {
                group.setColor(null);
                plugin.getAccountStorage().saveGroup(group);
                plugin.getPanel().rebuild();
            });
            colorMenu.add(resetColor);
        menu.add(colorMenu);

        menu.addSeparator();

        JMenuItem deleteItem = new JMenuItem("Delete Category");
        deleteItem.setForeground(Theme.BUTTON_DANGER);
        deleteItem.addActionListener(e -> confirmDelete());
        menu.add(deleteItem);

        return menu;
    }

    private JMenuItem createColorSwatch(Color color, String name)
    {
        // Plain Icon — the previous ImageIcon allocated a 12×12 backing image
        // its overridden paintIcon never used.
        Icon icon = new Icon()
        {
            @Override
            public void paintIcon(Component c, Graphics g, int x, int y)
            {
                g.setColor(color);
                g.fillRect(x, y, 12, 12);
                g.setColor(Theme.CARD_BORDER);
                g.drawRect(x, y, 11, 11);
            }

            @Override
            public int getIconWidth() { return 12; }

            @Override
            public int getIconHeight() { return 12; }
        };

        JMenuItem item = new JMenuItem(name, icon);
        item.addActionListener(e -> {
            group.setColor(Theme.colorToHex(color));
            plugin.getAccountStorage().saveGroup(group);
            plugin.getPanel().rebuild();
        });
        return item;
    }

    private JPanel buildFormPanel()
    {
        // Container only — the InlineAccountForm inside is built lazily by
        // ensureAddForm() on first show. Every category constructed one of
        // these forms (~10 components) on every rebuild for a panel that
        // stays hidden until the user clicks "+".
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(Theme.FORM_BACKGROUND);
        panel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(Theme.CARD_BORDER, 1),
            new EmptyBorder(0, 0, 0, 0)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 180));
        panel.setVisible(false);
        return panel;
    }

    private void ensureAddForm()
    {
        if (addForm != null)
        {
            return;
        }
        addForm = new InlineAccountForm(plugin, null, false, group.getId());
        addForm.setOnSave(profile -> {
            plugin.getAccountStorage().saveAccount(profile);
            addForm.clearFields();
            addFormPanel.setVisible(false);
            addFormVisible = false;
            plugin.getPanel().rebuild();
        });
        addForm.setOnCancel(() -> {
            addForm.clearFields();
            addFormPanel.setVisible(false);
            addFormVisible = false;
        });
        addFormPanel.add(addForm, BorderLayout.CENTER);
    }

    private void renameCategory()
    {
        String newName = JOptionPane.showInputDialog(
            SwingUtilities.getWindowAncestor(plugin.getPanel()),
            "Enter new category name:",
            group.getName()
        );
        if (newName != null && !newName.trim().isEmpty())
        {
            group.setName(newName.trim());
            plugin.getAccountStorage().saveGroup(group);
            plugin.getPanel().rebuild();
        }
    }

    private void confirmDelete()
    {
        int result = JOptionPane.showConfirmDialog(
            SwingUtilities.getWindowAncestor(plugin.getPanel()),
            "Delete category \"" + group.getName() + "\"?\n" +
                "Accounts in this category will be moved to Uncategorized.",
            "Confirm Delete",
            JOptionPane.YES_NO_OPTION,
            JOptionPane.WARNING_MESSAGE
        );
        if (result == JOptionPane.YES_OPTION)
        {
            plugin.getAccountStorage().deleteGroup(group.getId());
            plugin.getPanel().rebuild();
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.ui.components.Theme;
import com.mylosis.roster.ui.dnd.CategoryDragListener;
import com.mylosis.roster.ui.dnd.DragDropManager;
import com.mylosis.roster.ui.dnd.AccountDragListener;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.Map;

@Slf4j
public class CategoryPanel extends JPanel
{
    private final RosterPlugin plugin;
    @Getter
    private final ProfileGroup group;
    private final List<Account> profiles;
    private final DragDropManager dragDropManager;
    private final CategoryFormHandler formHandler;
    /** The owning panel — passed in directly because plugin.getPanel() is not yet
     *  populated during the very first rebuild (it runs inside the RosterPanel
     *  constructor, before RosterPlugin's field is assigned). */
    private final RosterPanel ownerPanel;

    private final JPanel contentWrapper;
    /** The header's collapse chevron, assigned in {@link #createHeader()} and
     *  updated by {@link #updateCollapsedState()}. Single source of truth (a
     *  previous revision kept a second, never-displayed label in sync). */
    private JLabel chevronLabel;
    /** Header component, exposed via {@link #getHeaderHeight()} so the drag
     *  target finder can use the real header bounds instead of assuming 45px. */
    private JPanel headerPanel;
    private boolean collapsed;

    /**
     * @param groupsById pre-resolved group lookup shared by all cards built in this
     *                   rebuild pass — saves an O(n) storage scan per card border.
     * @param ownerPanel the RosterPanel hosting these cards. Passed in explicitly
     *                   because plugin.getPanel() is null during the first rebuild
     *                   (it runs inside RosterPanel's own constructor).
     */
    public CategoryPanel(RosterPlugin plugin, ProfileGroup group, List<Account> profiles,
                         DragDropManager dragDropManager, Map<String, ProfileGroup> groupsById,
                         RosterPanel ownerPanel)
    {
        this.plugin = plugin;
        this.group = group;
        this.profiles = profiles;
        this.dragDropManager = dragDropManager;
        this.ownerPanel = ownerPanel;
        this.collapsed = group.isCollapsed();
        this.formHandler = new CategoryFormHandler(plugin, group, this::toggleCollapsed);

        setLayout(new BorderLayout());
        setBackground(Theme.BACKGROUND);
        setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        add(createHeader(), BorderLayout.NORTH);

        boolean gridMode = plugin.getConfig().gridView();

        contentWrapper = new JPanel();
        contentWrapper.setBackground(Theme.BACKGROUND);

        if (gridMode)
        {
            // Grid: use GridLayout inside a NORTH-aligned wrapper so it doesn't stretch
            int cols = 2;
            JPanel gridPanel = new JPanel(new GridLayout(0, cols, Theme.SPACING_XS, Theme.SPACING_XS));
            gridPanel.setBackground(Theme.BACKGROUND);

            for (Account profile : profiles)
            {
                AccountCardPanel card = new AccountCardPanel(plugin, profile, ownerPanel, groupsById);
                AccountDragListener dragListener = new AccountDragListener(dragDropManager, profile, card);
                dragListener.attachToComponent(card);
                gridPanel.add(card);
                if (ownerPanel != null) ownerPanel.registerCard(profile.getId(), card);
            }

            contentWrapper.setLayout(new BorderLayout());
            contentWrapper.setBorder(new EmptyBorder(Theme.SPACING_SM, 0, 0, 0));
            contentWrapper.add(gridPanel, BorderLayout.NORTH);
            contentWrapper.add(formHandler.getOrCreateFormPanel(), BorderLayout.CENTER);
        }
        else
        {
            contentWrapper.setLayout(new BoxLayout(contentWrapper, BoxLayout.Y_AXIS));
            contentWrapper.setBorder(new EmptyBorder(Theme.SPACING_SM, 0, 0, 0));

            for (Account profile : profiles)
            {
                AccountCardPanel card = new AccountCardPanel(plugin, profile, ownerPanel, groupsById);
                AccountDragListener dragListener = new AccountDragListener(dragDropManager, profile, card);
                dragListener.attachToComponent(card);
                contentWrapper.add(card);
                contentWrapper.add(Box.createVerticalStrut(Theme.SPACING_XS));
                if (ownerPanel != null) ownerPanel.registerCard(profile.getId(), card);
            }

            contentWrapper.add(formHandler.getOrCreateFormPanel());
        }

        add(contentWrapper, BorderLayout.CENTER);

        updateCollapsedState();
    }

    /**
     * Height of the category header row, or 0 if not yet laid out. Used by
     * {@code DropTargetFinder} to size the category-reorder hit zone.
     */
    public int getHeaderHeight()
    {
        return headerPanel != null ? headerPanel.getHeight() : 0;
    }

    private JPanel createHeader()
    {
        JPanel headerPanel = new JPanel(new BorderLayout(Theme.SPACING_MD, 0));
        this.headerPanel = headerPanel;
        headerPanel.setBackground(Theme.GROUP_HEADER);
        headerPanel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, Theme.CARD_BORDER),
            new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_MD)
        ));
        headerPanel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        JPanel leftPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, Theme.SPACING_SM, 0));
        leftPanel.setOpaque(false);

        // Chevron colored by category color when enabled
        Color catColor = Theme.parseColor(group.getColor());

        chevronLabel = new JLabel(collapsed ? "\u25B6" : "\u25BC");
        chevronLabel.setForeground(catColor != null ? catColor : Theme.TEXT_SECONDARY);
        chevronLabel.setFont(Theme.fontRegular(chevronLabel.getFont(), Theme.FONT_SIZE_TINY));
        leftPanel.add(chevronLabel);

        // Category names are user-controlled (and importable) — never let them
        // activate the HTML renderer.
        JLabel nameLabel = AccountCardHelper.plainTextOnly(new JLabel(group.getName()));
        nameLabel.setForeground(Theme.TEXT_PRIMARY);
        nameLabel.setFont(Theme.fontBold(nameLabel.getFont(), Theme.FONT_SIZE_BODY));
        leftPanel.add(nameLabel);

        JLabel countLabel = new JLabel("\u2022 " + profiles.size());
        countLabel.setForeground(Theme.TEXT_SECONDARY);
        countLabel.setFont(Theme.fontBold(countLabel.getFont(), Theme.FONT_SIZE_BODY));
        leftPanel.add(countLabel);

        headerPanel.add(leftPanel, BorderLayout.CENTER);

        JPanel rightPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        rightPanel.setOpaque(false);
        rightPanel.add(createAddButton());
        rightPanel.add(createMenuButton());
        headerPanel.add(rightPanel, BorderLayout.EAST);

        CategoryDragListener categoryDragListener = new CategoryDragListener(dragDropManager, group);
        headerPanel.addMouseListener(categoryDragListener);
        headerPanel.addMouseMotionListener(categoryDragListener);

        headerPanel.addMouseListener(new MouseAdapter()
        {
            private long pressTime = 0;
            private Point pressPoint = null;

            @Override
            public void mousePressed(MouseEvent e) { pressTime = System.currentTimeMillis(); pressPoint = e.getPoint(); }

            @Override
            public void mouseReleased(MouseEvent e)
            {
                if (pressPoint != null)
                {
                    long duration = System.currentTimeMillis() - pressTime;
                    int dx = Math.abs(e.getPoint().x - pressPoint.x);
                    int dy = Math.abs(e.getPoint().y - pressPoint.y);
                    if (duration < 300 && dx < 5 && dy < 5 && e.getButton() == MouseEvent.BUTTON1)
                    {
                        // updateCollapsedState() flips the chevron too.
                        toggleCollapsed();
                    }
                }
                pressPoint = null;
            }

            @Override
            public void mouseEntered(MouseEvent e) { headerPanel.setBackground(Theme.GROUP_HEADER_HOVER); }

            @Override
            public void mouseExited(MouseEvent e) { headerPanel.setBackground(Theme.GROUP_HEADER); }
        });

        return headerPanel;
    }

    private JButton createAddButton()
    {
        JButton button = new JButton("+");
        button.setBackground(Theme.GROUP_HEADER);
        button.setForeground(Theme.TEXT_SECONDARY);
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setPreferredSize(new Dimension(28, Theme.BUTTON_HEIGHT_SM));
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setToolTipText("Add account to this category");
        button.setFont(button.getFont().deriveFont(Font.BOLD, 18f));
        button.addActionListener(e -> formHandler.toggleAddForm(collapsed, this));
        button.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e) { e.consume(); }

            @Override
            public void mouseEntered(MouseEvent e) { button.setBackground(Theme.BUTTON_PRIMARY); button.setForeground(Theme.TEXT_PRIMARY); }

            @Override
            public void mouseExited(MouseEvent e) { button.setBackground(Theme.GROUP_HEADER); button.setForeground(Theme.TEXT_SECONDARY); }
        });
        return button;
    }

    private JButton createMenuButton()
    {
        JButton button = new JButton("\u22EE");
        button.setBackground(Theme.GROUP_HEADER);
        button.setForeground(Theme.TEXT_SECONDARY);
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setPreferredSize(new Dimension(24, Theme.BUTTON_HEIGHT_SM));
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        // Built on first click — the category menu (incl. the color submenu's
        // ten items) was constructed for every category on every rebuild.
        JPopupMenu[] menuRef = new JPopupMenu[1];
        button.addActionListener(e -> {
            if (menuRef[0] == null)
            {
                menuRef[0] = formHandler.createContextMenu();
            }
            menuRef[0].show(button, 0, button.getHeight());
        });
        button.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e) { e.consume(); }

            @Override
            public void mouseEntered(MouseEvent e) { button.setBackground(Theme.GROUP_HEADER_HOVER); }

            @Override
            public void mouseExited(MouseEvent e) { button.setBackground(Theme.GROUP_HEADER); }
        });
        return button;
    }

    private void toggleCollapsed()
    {
        collapsed = !collapsed;
        group.setCollapsed(collapsed);
        plugin.getAccountStorage().saveGroup(group);
        updateCollapsedState();
    }

    private void updateCollapsedState()
    {
        contentWrapper.setVisible(!collapsed);
        chevronLabel.setText(collapsed ? "\u25B6" : "\u25BC");
        revalidate();
        repaint();
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.ui.components.InlineAccountForm;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import java.awt.*;

/**
 * Manages the expand/collapse behavior and inline edit form for a AccountCardPanel.
 */
public class CardExpansionHandler
{
    private final RosterPlugin plugin;
    private final Account profile;
    private final RosterConfig config;
    private final RosterPanel parentPanel;
    private final JPanel ownerCard;
    private final JPanel headerPanel;

    private JPanel formPanel;
    private InlineAccountForm editForm;
    private boolean expanded = false;

    public CardExpansionHandler(RosterPlugin plugin, Account profile,
                                RosterPanel parentPanel, JPanel ownerCard, JPanel headerPanel)
    {
        this.plugin = plugin;
        this.profile = profile;
        this.config = plugin.getConfig();
        this.parentPanel = parentPanel;
        this.ownerCard = ownerCard;
        this.headerPanel = headerPanel;
    }

    public JPanel createFormPanel()
    {
        // The edit form itself is built lazily in ensureEditForm(): every card
        // gets a form panel on every rebuild, but the ~10 components of an
        // InlineAccountForm are only needed when a card is actually expanded.
        // Building them eagerly dominated rebuild cost (100 cards ≈ 1000+
        // component constructions per rebuild) for forms nobody ever saw.
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(Theme.FORM_BACKGROUND);
        panel.setBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, Theme.CARD_BORDER));
        formPanel = panel;
        return panel;
    }

    private void ensureEditForm()
    {
        if (editForm != null)
        {
            return;
        }
        editForm = new InlineAccountForm(plugin, profile, true, null);
        editForm.setOnSave(savedAccount -> {
            plugin.getAccountStorage().saveAccount(savedAccount);
            collapse();
            plugin.getPanel().rebuild();
        });
        editForm.setOnCancel(this::collapse);
        formPanel.add(editForm, BorderLayout.CENTER);
    }

    public boolean isExpanded()
    {
        return expanded;
    }

    public void toggleExpanded()
    {
        if (expanded) collapse();
        else expand();
    }

    public void expand()
    {
        if (expanded) return;
        if (parentPanel != null)
        {
            parentPanel.collapseExpandedCard();
            parentPanel.setExpandedCard((AccountCardPanel) ownerCard);
        }
        expanded = true;
        ensureEditForm();
        formPanel.setVisible(true);

        // Calculate exact needed height: header + form + border
        int headerHeight = headerPanel.getPreferredSize().height;
        int formHeight = formPanel.getPreferredSize().height;
        Insets insets = ownerCard.getInsets();
        int totalHeight = headerHeight + formHeight + insets.top + insets.bottom;
        ownerCard.setMaximumSize(new Dimension(Integer.MAX_VALUE, totalHeight));
        ownerCard.setPreferredSize(new Dimension(ownerCard.getWidth(), totalHeight));

        editForm.focusUsernameField();
        revalidateAncestors();
    }

    public void collapse()
    {
        if (!expanded) return;
        expanded = false;
        formPanel.setVisible(false);
        int cardHeight = Theme.CARD_HEIGHT;
        ownerCard.setMaximumSize(new Dimension(Integer.MAX_VALUE, cardHeight));
        ownerCard.setPreferredSize(null);
        if (parentPanel != null) parentPanel.setExpandedCard(null);
        revalidateAncestors();
    }

    private void revalidateAncestors()
    {
        // Scope the revalidate/repaint to the enclosing scroll pane, the same
        // boundary RosterPanel.rebuild() uses — the card only changes layout
        // inside the viewport. Walking every ancestor to the window repainted
        // the entire RuneLite client per expand/collapse.
        ownerCard.revalidate();
        Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, ownerCard);
        if (scrollPane != null)
        {
            scrollPane.revalidate();
            scrollPane.repaint();
        }
        else
        {
            ownerCard.repaint();
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.storage.AccountStorage;
import com.mylosis.roster.ui.components.InlineAccountForm;
import com.mylosis.roster.ui.components.Theme;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

/**
 * Manages the inline add-profile and add-category forms.
 */
@Slf4j
public class PanelFormManager
{
    private final RosterPlugin plugin;
    private final AccountStorage storage;
    private final Runnable onRebuild;
    private final Runnable onRevalidate;

    private JPanel addAccountFormPanel;
    private InlineAccountForm addAccountForm;
    private boolean addFormVisible = false;

    private JPanel addCategoryFormPanel;
    private JTextField categoryNameField;
    private boolean addCategoryFormVisible = false;

    public PanelFormManager(RosterPlugin plugin, Runnable onRebuild, Runnable onRevalidate)
    {
        this.plugin = plugin;
        this.storage = plugin.getAccountStorage();
        this.onRebuild = onRebuild;
        this.onRevalidate = onRevalidate;
    }

    public JPanel getAddProfileFormPanel()
    {
        if (addAccountFormPanel == null)
        {
            addAccountFormPanel = buildAddProfileFormPanel();
        }
        return addAccountFormPanel;
    }

    public JPanel getAddCategoryFormPanel()
    {
        if (addCategoryFormPanel == null)
        {
            addCategoryFormPanel = buildAddCategoryFormPanel();
        }
        return addCategoryFormPanel;
    }

    public boolean isAddFormVisible()
    {
        return addFormVisible;
    }

    public void hideAddForm()
    {
        if (addFormVisible)
        {
            addAccountFormPanel.setVisible(false);
            addFormVisible = false;
        }
    }

    public void toggleAddProfileForm(Runnable collapseExpandedCard)
    {
        if (addAccountFormPanel == null)
        {
            log.error("addAccountFormPanel is null!");
            return;
        }

        if (addCategoryFormVisible)
        {
            addCategoryFormPanel.setVisible(false);
            addCategoryFormVisible = false;
        }

        if (!addFormVisible)
        {
            collapseExpandedCard.run();
        }

        addFormVisible = !addFormVisible;
        addAccountFormPanel.setVisible(addFormVisible);

        if (addFormVisible)
        {
            SwingUtilities.invokeLater(() -> {
                if (addAccountForm != null)
                {
                    addAccountForm.focusUsernameField();
                }
            });
        }

        onRevalidate.run();
    }

    public void toggleAddCategoryForm(Runnable collapseExpandedCard)
    {
        if (addFormVisible)
        {
            addAccountFormPanel.setVisible(false);
            addFormVisible = false;
        }

        collapseExpandedCard.run();

        addCategoryFormVisible = !addCategoryFormVisible;
        addCategoryFormPanel.setVisible(addCategoryFormVisible);

        if (addCategoryFormVisible)
        {
            categoryNameField.setText("");
            SwingUtilities.invokeLater(() -> categoryNameField.requestFocusInWindow());
        }

        onRevalidate.run();
    }

    private JPanel buildAddProfileFormPanel()
    {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(Theme.FORM_BACKGROUND);
        panel.setBorder(BorderFactory.createCompoundBorder(
            new EmptyBorder(Theme.SPACING_SM, 0, 0, 0),
            BorderFactory.createLineBorder(Theme.CARD_BORDER, 1)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 170));
        panel.setPreferredSize(new Dimension(200, 170));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.setVisible(false);

        addAccountForm = new InlineAccountForm(plugin, null, true, null);
        addAccountForm.setOnSave(profile -> {
            storage.saveAccount(profile);
            addAccountForm.clearFields();
            panel.setVisible(false);
            addFormVisible = false;
            onRebuild.run();
        });
        addAccountForm.setOnCancel(() -> {
            addAccountForm.clearFields();
            panel.setVisible(false);
            addFormVisible = false;
            onRevalidate.run();
        });

        panel.add(addAccountForm, BorderLayout.CENTER);
        return panel;
    }

    private JPanel buildAddCategoryFormPanel()
    {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(Theme.FORM_BACKGROUND);
        panel.setBorder(BorderFactory.createCompoundBorder(
            new EmptyBorder(Theme.SPACING_SM, 0, 0, 0),
            BorderFactory.createLineBorder(Theme.CARD_BORDER, 1)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 70));
        panel.setPreferredSize(new Dimension(200, 70));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.setVisible(false);

        JPanel innerPanel = new JPanel();
        innerPanel.setLayout(new BoxLayout(innerPanel, BoxLayout.Y_AXIS));
        innerPanel.setBackground(Theme.FORM_BACKGROUND);
        innerPanel.setBorder(new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM));

        innerPanel.add(buildCategoryNameRow());
        innerPanel.add(Box.createVerticalStrut(Theme.SPACING_SM));
        innerPanel.add(buildCategoryButtonRow());

        panel.add(innerPanel, BorderLayout.CENTER);

        categoryNameField.getInputMap().put(KeyStroke.getKeyStroke("ESCAPE"), "cancel");
        categoryNameField.getActionMap().put("cancel", new AbstractAction()
        {
            @Override
            public void actionPerformed(java.awt.event.ActionEvent e)
            {
                cancelCategoryForm();
            }
        });

        return panel;
    }

    private JPanel buildCategoryNameRow()
    {
        JPanel nameRow = new JPanel(new BorderLayout(Theme.SPACING_XS, 0));
        nameRow.setOpaque(false);
        nameRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT));
        nameRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel nameLabel = new JLabel("Name");
        nameLabel.setForeground(Theme.TEXT_SECONDARY);
        nameLabel.setFont(Theme.fontRegular(nameLabel.getFont(), Theme.FONT_SIZE_SMALL));
        nameLabel.setPreferredSize(new Dimension(55, Theme.BUTTON_HEIGHT));
        nameRow.add(nameLabel, BorderLayout.WEST);

        categoryNameField = new JTextField();
        categoryNameField.setBackground(Theme.BACKGROUND_DARKER);
        categoryNameField.setForeground(Theme.TEXT_PRIMARY);
        categoryNameField.setCaretColor(Theme.TEXT_PRIMARY);
        categoryNameField.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(Theme.CARD_BORDER),
            new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM)
        ));
        categoryNameField.setFont(Theme.fontRegular(categoryNameField.getFont(), Theme.FONT_SIZE_BODY));
        categoryNameField.addActionListener(e -> saveCategoryForm());
        nameRow.add(categoryNameField, BorderLayout.CENTER);

        return nameRow;
    }

    private JPanel buildCategoryButtonRow()
    {
        JPanel buttonPanel = new JPanel(new GridLayout(1, 2, Theme.SPACING_XS, 0));
        buttonPanel.setOpaque(false);
        buttonPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT_SM));
        buttonPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JButton cancelButton = new JButton("Cancel");
        cancelButton.setBackground(Theme.BUTTON_SECONDARY);
        cancelButton.setForeground(Theme.TEXT_PRIMARY);
        cancelButton.setFocusPainted(false);
        cancelButton.setBorderPainted(false);
        cancelButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        cancelButton.setFont(Theme.fontRegular(cancelButton.getFont(), Theme.FONT_SIZE_HEADING));
        cancelButton.addActionListener(e -> cancelCategoryForm());
        buttonPanel.add(cancelButton);

        JButton saveButton = new JButton("Save");
        saveButton.setBackground(Theme.BUTTON_PRIMARY);
        saveButton.setForeground(Theme.TEXT_PRIMARY);
        saveButton.setFocusPainted(false);
        saveButton.setBorderPainted(false);
        saveButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        saveButton.setFont(Theme.fontRegular(saveButton.getFont(), Theme.FONT_SIZE_HEADING));
        saveButton.addActionListener(e -> saveCategoryForm());
        buttonPanel.add(saveButton);

        return buttonPanel;
    }

    private void saveCategoryForm()
    {
        String name = categoryNameField.getText().trim();
        if (!name.isEmpty())
        {
            ProfileGroup group = ProfileGroup.createNew(name);
            // Auto-assign a default color based on existing category count
            int existingCount = storage.getGroups().size();
            Color[] palette = Theme.DEFAULT_CATEGORY_COLORS;
            if (existingCount < palette.length)
            {
                Color c = palette[existingCount];
                group.setColor(String.format("#%02X%02X%02X", c.getRed(), c.getGreen(), c.getBlue()));
            }
            storage.saveGroup(group);
            categoryNameField.setText("");
            addCategoryFormPanel.setVisible(false);
            addCategoryFormVisible = false;
            onRebuild.run();
        }
    }

    private void cancelCategoryForm()
    {
        categoryNameField.setText("");
        addCategoryFormPanel.setVisible(false);
        addCategoryFormVisible = false;
        onRevalidate.run();
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import java.awt.*;

/**
 * Shared utility methods for profile card rendering.
 * Extracted from AccountCardPanel to keep file sizes manageable.
 */
public final class AccountCardHelper
{
    private AccountCardHelper() {} // Prevent instantiation

    /**
     * Creates a small green dot indicating the profile is currently logged in.
     */
    public static JPanel createOnlineDot()
    {
        int size = Theme.ONLINE_DOT_SIZE;
        JPanel dot = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                super.paintComponent(g);
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(Theme.ONLINE_INDICATOR);
                g2.fillOval(0, 0, size, size);
                g2.dispose();
            }
        };
        dot.setOpaque(false);
        dot.setPreferredSize(new Dimension(size, size));
        dot.setMaximumSize(new Dimension(size, size));
        dot.setToolTipText("Currently logged in");
        return dot;
    }

    /**
     * Creates a JLabel that truncates text beyond maxChars with an ellipsis.
     */
    public static JLabel createTruncatingLabel(String text, Color color, Font font, int maxChars)
    {
        String display = text;
        if (text != null && text.length() > maxChars)
        {
            // Truncate at last space before limit to avoid cutting mid-word
            String trimmed = text.substring(0, maxChars);
            int lastSpace = trimmed.lastIndexOf(' ');
            display = (lastSpace > maxChars / 2) ? trimmed.substring(0, lastSpace) + "..." : trimmed + "...";
        }
        JLabel label = new JLabel(display);
        // User-controlled text (alias/login/notes — importable from clipboard
        // JSON) must never activate Swing's HTML renderer: a value starting
        // with <html> would break rendering, and an embedded <img src> fires
        // an outbound HTTP request when the label paints.
        label.putClientProperty("html.disable", Boolean.TRUE);
        label.setForeground(color);
        label.setFont(font);
        if (text != null && text.length() > maxChars) label.setToolTipText(safeTooltip(text));
        return label;
    }

    /**
     * Returns a tooltip-safe version of user-controlled text. Normal strings
     * pass through untouched (identical rendering); strings Swing would treat
     * as HTML are escaped so they display as literal text instead.
     */
    public static String safeTooltip(String text)
    {
        if (text == null || !javax.swing.plaf.basic.BasicHTML.isHTMLString(text))
        {
            return text;
        }
        return "<html>" + escapeHtml(text) + "</html>";
    }

    /**
     * Disables HTML interpretation on a label that displays user-controlled
     * text. Returns the label for chaining.
     */
    public static JLabel plainTextOnly(JLabel label)
    {
        label.putClientProperty("html.disable", Boolean.TRUE);
        return label;
    }

    /**
     * Escapes HTML special characters for safe display in HTML-rendered labels.
     */
    public static String escapeHtml(String text)
    {
        if (text == null) return "";
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace("\"", "&quot;").replace("\n", "<br>");
    }

    /**
     * Revalidates and repaints the component's enclosing scroll pane — the
     * layout boundary for anything inside the plugin's card list. This used to
     * walk every ancestor up to (and including) the RuneLite window, repainting
     * the whole client per call.
     */
    public static void revalidateToWindow(Component component)
    {
        component.revalidate();
        Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, component);
        if (scrollPane != null)
        {
            scrollPane.revalidate();
            scrollPane.repaint();
        }
        else
        {
            component.repaint();
        }
    }

    /**
     * Formats a millisecond timestamp as a coarse relative-time string
     * (e.g. "just now", "5m ago", "3h ago", "2d ago", "4mo ago", "1y ago").
     * Returns null for null or future-dated input.
     */
    public static String formatTimeAgo(Long epochMillis)
    {
        if (epochMillis == null)
        {
            return null;
        }
        long diff = System.currentTimeMillis() - epochMillis;
        if (diff < 0)
        {
            return null;
        }

        long minute = 60_000L;
        long hour = 60 * minute;
        long day = 24 * hour;
        long month = 30 * day;
        long year = 365 * day;

        if (diff < 2 * minute) return "just now";
        if (diff < hour)       return (diff / minute) + "m ago";
        if (diff < day)        return (diff / hour)   + "h ago";
        if (diff < month)      return (diff / day)    + "d ago";
        if (diff < year)       return (diff / month)  + "mo ago";
        return (diff / year) + "y ago";
    }

    /**
     * Resolves the display name for a profile based on privacy settings.
     * Used by both AccountCardPanel (list view) and GridAccountBuilder (grid view).
     */
    public static String resolveDisplayName(Account profile, RosterConfig config)
    {
        boolean allHidden = config.hideAlias() && config.hideLogin();
        String displayName;
        if (allHidden)
        {
            displayName = "Account";
        }
        else if (config.hideAlias())
        {
            displayName = profile.getUsername();
        }
        else
        {
            displayName = profile.getDisplayName();
        }
        if (displayName == null) displayName = profile.getUsername();
        return displayName;
    }
}

package com.mylosis.roster.ui;

import com.google.gson.Gson;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.ui.components.NotificationToast;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import java.awt.*;
import java.awt.datatransfer.StringSelection;

/**
 * Handles context menu actions for an account card:
 * edit, copy username, move to category, and delete.
 */
public class AccountCardActions
{
    private final RosterPlugin plugin;
    private final Account profile;
    private final Runnable onExpand;

    public AccountCardActions(RosterPlugin plugin, Account profile, Runnable onExpand)
    {
        this.plugin = plugin;
        this.profile = profile;
        this.onExpand = onExpand;
    }

    public JPopupMenu createContextMenu()
    {
        JPopupMenu menu = new JPopupMenu();

        JMenuItem editItem = new JMenuItem("Edit");
        editItem.addActionListener(e -> onExpand.run());
        menu.add(editItem);

        JMenuItem copyUsernameItem = new JMenuItem("Copy Username");
        copyUsernameItem.addActionListener(e -> copyToClipboard(profile.getUsername()));
        menu.add(copyUsernameItem);

        JMenuItem exportItem = new JMenuItem("Export to Clipboard");
        exportItem.addActionListener(e -> exportProfile());
        menu.add(exportItem);

        menu.addSeparator();

        JMenuItem moveToCategoryItem = new JMenuItem("Move to Category...");
        moveToCategoryItem.addActionListener(e -> showMoveToCategoryDialog());
        menu.add(moveToCategoryItem);

        menu.addSeparator();

        JMenuItem deleteItem = new JMenuItem("Delete");
        deleteItem.setForeground(Theme.BUTTON_DANGER);
        deleteItem.addActionListener(e -> confirmDelete());
        menu.add(deleteItem);

        return menu;
    }

    private void showMoveToCategoryDialog()
    {
        var groups = plugin.getAccountStorage().getGroups();

        // Wrapper objects (toString = name) instead of name strings: resolving
        // the selection back via indexOf(name) sent the account to the FIRST
        // category with that name whenever two categories shared a name.
        GroupComboItem[] choices = new GroupComboItem[groups.size() + 1];
        choices[0] = new GroupComboItem(null, "Uncategorized");
        for (int i = 0; i < groups.size(); i++)
        {
            choices[i + 1] = new GroupComboItem(groups.get(i).getId(), groups.get(i).getName());
        }

        GroupComboItem selected = (GroupComboItem) JOptionPane.showInputDialog(
            SwingUtilities.getWindowAncestor(plugin.getPanel()),
            "Select category:",
            "Move to Category",
            JOptionPane.PLAIN_MESSAGE,
            null,
            choices,
            choices[0]
        );

        if (selected != null)
        {
            profile.setGroupId(selected.id);
            plugin.getAccountStorage().saveAccount(profile);
            plugin.getPanel().rebuild();
        }
    }

    private void confirmDelete()
    {
        if (plugin.getConfig().confirmDelete())
        {
            int result = JOptionPane.showConfirmDialog(
                SwingUtilities.getWindowAncestor(plugin.getPanel()),
                "Are you sure you want to delete \"" + profile.getDisplayName() + "\"?",
                "Confirm Delete",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE
            );

            if (result != JOptionPane.YES_OPTION)
            {
                return;
            }
        }

        plugin.getAccountStorage().deleteProfile(profile.getId());
        plugin.getPanel().rebuild();
    }

    private void exportProfile()
    {
        Gson gson = plugin.getGson().newBuilder().setPrettyPrinting().create();
        // Wrap single profile in AccountData envelope for consistent import format
        AccountData wrapper = AccountData.builder()
            .version(AccountData.CURRENT_VERSION)
            .accounts(java.util.Collections.singletonList(profile))
            .groups(new java.util.ArrayList<>())
            .build();
        String json = gson.toJson(wrapper);
        copyToClipboard(json);
        if (plugin.getPanel() != null)
        {
            plugin.getPanel().showNotification("Exported " + profile.getDisplayName(), NotificationToast.Type.SUCCESS);
        }
    }

    private void copyToClipboard(String text)
    {
        if (text != null)
        {
            Toolkit.getDefaultToolkit()
                .getSystemClipboard()
                .setContents(new StringSelection(text), null);
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.model.SortKey;
import com.mylosis.roster.storage.AccountStorage;
import com.mylosis.roster.ui.components.Icons;
import com.mylosis.roster.ui.components.Theme;
import com.mylosis.roster.ui.dnd.DragDropManager;
import com.mylosis.roster.ui.dnd.AccountDragListener;

import java.util.Comparator;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Builds the scrollable profile list content.
 * Handles filtering, grouping, and empty state rendering.
 */
public class AccountListBuilder
{
    private final RosterPlugin plugin;
    private final AccountStorage storage;
    private final RosterPanel parentPanel;
    private final DragDropManager dragDropManager;

    public AccountListBuilder(RosterPlugin plugin, RosterPanel parentPanel,
                              DragDropManager dragDropManager)
    {
        this.plugin = plugin;
        this.storage = plugin.getAccountStorage();
        this.parentPanel = parentPanel;
        this.dragDropManager = dragDropManager;
    }

    /**
     * Rebuild the profile list into the target panel.
     * Returns the count of filtered profiles for the footer label.
     */
    public int[] rebuild(JPanel targetPanel, String searchFilter)
    {
        targetPanel.removeAll();

        List<Account> allProfiles = storage.getAccounts();
        List<Account> filteredProfiles = filterProfiles(allProfiles, searchFilter);
        List<ProfileGroup> sortedGroups = getSortedGroups();
        // Resolve group-by-id once per rebuild. Used by both the grouping pass
        // below and by AccountCardPanel when it needs the category color for its
        // border — previously each card did its own storage.getGroup() lookup,
        // which was O(n*m) in card and group counts.
        Map<String, ProfileGroup> groupsById = new HashMap<>(sortedGroups.size() * 2);
        for (ProfileGroup g : sortedGroups) groupsById.put(g.getId(), g);
        Set<String> addedProfileIds = new HashSet<>();

        buildGroupedProfiles(targetPanel, filteredProfiles, sortedGroups, groupsById, addedProfileIds, searchFilter);
        buildUngroupedProfiles(targetPanel, filteredProfiles, sortedGroups, groupsById, addedProfileIds);

        if (filteredProfiles.isEmpty() && sortedGroups.isEmpty())
        {
            targetPanel.add(createEmptyStatePanel(searchFilter));
        }

        targetPanel.revalidate();
        targetPanel.repaint();

        return new int[]{filteredProfiles.size(), allProfiles.size()};
    }

    private List<ProfileGroup> getSortedGroups()
    {
        List<ProfileGroup> groups = new ArrayList<>(storage.getGroups());
        groups.sort((a, b) -> Integer.compare(a.getSortOrder(), b.getSortOrder()));
        return groups;
    }

    private void buildGroupedProfiles(JPanel target, List<Account> filteredProfiles,
                                      List<ProfileGroup> groups, Map<String, ProfileGroup> groupsById,
                                      Set<String> addedProfileIds, String searchFilter)
    {
        // Bucket profiles by groupId in one pass instead of scanning the filtered
        // list once per group. Previous O(groups * profiles); now O(profiles + groups).
        Map<String, List<Account>> byGroup = new HashMap<>(groups.size() * 2);
        for (Account profile : filteredProfiles)
        {
            String gid = profile.getGroupId();
            if (gid != null && groupsById.containsKey(gid))
            {
                byGroup.computeIfAbsent(gid, k -> new ArrayList<>()).add(profile);
                addedProfileIds.add(profile.getId());
            }
        }

        for (ProfileGroup group : groups)
        {
            List<Account> groupProfiles = byGroup.get(group.getId());
            if (groupProfiles == null)
            {
                groupProfiles = new ArrayList<>();
            }
            sortBySortOrder(groupProfiles);

            if (!groupProfiles.isEmpty() || searchFilter.isEmpty())
            {
                CategoryPanel categoryPanel = new CategoryPanel(
                    plugin, group, groupProfiles, dragDropManager, groupsById, parentPanel);
                target.add(categoryPanel);
                target.add(Box.createVerticalStrut(Theme.SPACING_LG));
            }
        }
    }

    private void buildUngroupedProfiles(JPanel target, List<Account> filteredProfiles,
                                        List<ProfileGroup> groups, Map<String, ProfileGroup> groupsById,
                                        Set<String> addedProfileIds)
    {
        List<Account> ungrouped = new ArrayList<>();
        for (Account profile : filteredProfiles)
        {
            if (!addedProfileIds.contains(profile.getId()))
            {
                ungrouped.add(profile);
            }
        }

        if (ungrouped.isEmpty() && groups.isEmpty())
        {
            return;
        }

        sortBySortOrder(ungrouped);

        if (!groups.isEmpty())
        {
            target.add(createUncategorizedHeader());
            target.add(Box.createVerticalStrut(Theme.SPACING_SM));
        }

        if (!ungrouped.isEmpty())
        {
            boolean gridMode = plugin.getConfig().gridView();

            if (gridMode)
            {
                int cols = 2;
                JPanel gridPanel = new JPanel(new GridLayout(0, cols, Theme.SPACING_XS, Theme.SPACING_XS));
                gridPanel.setBackground(Theme.BACKGROUND);
                for (Account profile : ungrouped)
                {
                    AccountCardPanel card = new AccountCardPanel(plugin, profile, parentPanel, groupsById);
                    AccountDragListener dragListener = new AccountDragListener(dragDropManager, profile, card);
                    dragListener.attachToComponent(card);
                    gridPanel.add(card);
                    parentPanel.registerCard(profile.getId(), card);
                }
                JPanel wrapper = new JPanel(new BorderLayout());
                wrapper.setBackground(Theme.BACKGROUND);
                wrapper.add(gridPanel, BorderLayout.NORTH);
                // Marks the ungrouped card area as a drop zone: DropTargetFinder
                // hit-tests this container so drops land anywhere in the list,
                // not just on the header (which doesn't even exist without groups).
                wrapper.putClientProperty("UNCATEGORIZED_CONTAINER", Boolean.TRUE);
                target.add(wrapper);
            }
            else
            {
                JPanel ungroupedPanel = new JPanel();
                ungroupedPanel.setLayout(new BoxLayout(ungroupedPanel, BoxLayout.Y_AXIS));
                ungroupedPanel.setBackground(Theme.BACKGROUND);
                // Same drop-zone marker as the grid wrapper above.
                ungroupedPanel.putClientProperty("UNCATEGORIZED_CONTAINER", Boolean.TRUE);
                for (Account profile : ungrouped)
                {
                    AccountCardPanel card = new AccountCardPanel(plugin, profile, parentPanel, groupsById);
                    AccountDragListener dragListener = new AccountDragListener(dragDropManager, profile, card);
                    dragListener.attachToComponent(card);
                    ungroupedPanel.add(card);
                    ungroupedPanel.add(Box.createVerticalStrut(Theme.SPACING_XS));
                    parentPanel.registerCard(profile.getId(), card);
                }
                target.add(ungroupedPanel);
            }

            target.add(Box.createVerticalStrut(Theme.SPACING_SM));
        }
    }

    /**
     * Sort the profile list by the currently-active SortKey. MANUAL falls back to the
     * explicit per-account {@code sortOrder} (drag order), preserving v1.0 behaviour.
     * Non-manual keys never touch {@code sortOrder} — they sort a copy in place, so
     * switching back to MANUAL restores the user's hand-arranged drag order verbatim.
     */
    private void sortBySortOrder(List<Account> profiles)
    {
        SortKey key = plugin.getConfig().sortKey();
        profiles.sort(comparatorFor(key));
    }

    private static final Comparator<Account> NAME_ASC_COMPARATOR =
        // String.CASE_INSENSITIVE_ORDER is allocation-free per compare; the previous
        // safeLower() form allocated a temp String for every comparison, multiplied
        // by O(n log n) for each sort, repeated for every category on each rebuild.
        Comparator.comparing(Account::getDisplayName,
            Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER));

    private static final Comparator<Account> NAME_DESC_COMPARATOR = NAME_ASC_COMPARATOR.reversed();

    private static Comparator<Account> comparatorFor(SortKey key)
    {
        switch (key)
        {
            case NAME_ASC:
                return NAME_ASC_COMPARATOR;
            case NAME_DESC:
                return NAME_DESC_COMPARATOR;
            case LAST_ONLINE:
                // Recent first; never-seen accounts sink to the bottom
                return (a, b) -> Long.compare(lastOnline(b), lastOnline(a));
            case DATE_ADDED:
                // Newest first; pre-v1.1 accounts (no createdAt) sink to the bottom
                return (a, b) -> Long.compare(createdAt(b), createdAt(a));
            case MANUAL:
            default:
                return AccountData.SORT_ORDER_COMPARATOR;
        }
    }

    private static long lastOnline(Account a)
    {
        if (a.getMetadata() == null || a.getMetadata().getLastOnlineAt() == null)
        {
            return Long.MIN_VALUE;
        }
        return a.getMetadata().getLastOnlineAt();
    }

    private static long createdAt(Account a)
    {
        if (a.getMetadata() == null || a.getMetadata().getCreatedAt() == null)
        {
            return Long.MIN_VALUE;
        }
        return a.getMetadata().getCreatedAt();
    }

    private List<Account> filterProfiles(List<Account> profiles, String searchFilter)
    {
        if (searchFilter.isEmpty())
        {
            return new ArrayList<>(profiles);
        }

        // Account.getSearchHaystack() returns a cached lowercase concatenation of
        // the searchable fields, rebuilt only when the account changes. Previously
        // this was 3× toLowerCase per card per keystroke — at 100 accounts and a
        // 10-char query, that's 3000 throwaway String allocations.
        List<Account> filtered = new ArrayList<>();
        for (Account profile : profiles)
        {
            if (profile.getSearchHaystack().contains(searchFilter))
            {
                filtered.add(profile);
            }
        }
        return filtered;
    }

    private JPanel createEmptyStatePanel(String searchFilter)
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(Theme.BACKGROUND);
        panel.setBorder(new EmptyBorder(40, Theme.SPACING_LG, 40, Theme.SPACING_LG));

        JLabel iconLabel = new JLabel(Icons.get(Icons.USER, 48));
        iconLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        panel.add(iconLabel);
        panel.add(Box.createVerticalStrut(Theme.SPACING_LG));

        String messageText = searchFilter.isEmpty() ? "No accounts yet" : "No matching accounts";
        JLabel message = new JLabel(messageText);
        message.setForeground(Theme.TEXT_SECONDARY);
        message.setFont(Theme.fontRegular(message.getFont(), Theme.FONT_SIZE_HEADING));
        message.setAlignmentX(Component.CENTER_ALIGNMENT);
        panel.add(message);

        if (searchFilter.isEmpty())
        {
            panel.add(Box.createVerticalStrut(Theme.SPACING_SM));
            JLabel hint = new JLabel("Click + to add your first account");
            hint.setForeground(Theme.TEXT_SECONDARY);
            hint.setFont(Theme.fontRegular(hint.getFont(), Theme.FONT_SIZE_BODY));
            hint.setAlignmentX(Component.CENTER_ALIGNMENT);
            panel.add(hint);
        }

        return panel;
    }

    private JPanel createUncategorizedHeader()
    {
        JPanel header = new JPanel(new BorderLayout(Theme.SPACING_MD, 0));
        header.setBackground(Theme.GROUP_HEADER);
        header.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, Theme.CARD_BORDER),
            new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_MD)
        ));

        header.putClientProperty("UNCATEGORIZED_HEADER", Boolean.TRUE);

        JLabel label = new JLabel("Uncategorized");
        label.setForeground(Theme.TEXT_SECONDARY);
        label.setFont(Theme.fontBold(label.getFont(), Theme.FONT_SIZE_BODY));
        header.add(label, BorderLayout.CENTER);

        // Add profile button (matches category + button style)
        JButton addButton = new JButton("+");
        addButton.setBackground(Theme.GROUP_HEADER);
        addButton.setForeground(Theme.TEXT_SECONDARY);
        addButton.setFocusPainted(false);
        addButton.setBorderPainted(false);
        addButton.setPreferredSize(new Dimension(28, Theme.BUTTON_HEIGHT_SM));
        addButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        addButton.setToolTipText("Add account");
        addButton.setFont(addButton.getFont().deriveFont(Font.BOLD, 18f));
        addButton.addActionListener(e ->
            parentPanel.getFormManager().toggleAddProfileForm(
                parentPanel::collapseExpandedCard));
        addButton.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseEntered(java.awt.event.MouseEvent e) { addButton.setBackground(Theme.GROUP_HEADER_HOVER); }

            @Override
            public void mouseExited(java.awt.event.MouseEvent e) { addButton.setBackground(Theme.GROUP_HEADER); }
        });
        header.add(addButton, BorderLayout.EAST);

        return header;
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.model.AccountType;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.ui.components.AccountTypeBadge;
import com.mylosis.roster.ui.components.InlineAccountForm;
import com.mylosis.roster.ui.components.Theme;
import lombok.Getter;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.Map;

public class AccountCardPanel extends JPanel
{
    private final RosterPlugin plugin;
    @Getter
    private final Account profile;
    private final RosterConfig config;

    private boolean hovered = false;
    private Color currentBackground;
    private JPanel headerPanel;
    private CardExpansionHandler expansionHandler;
    private boolean gridEditMode = false;
    private RosterPanel parentPanel;
    /** Pre-resolved group lookup passed down from the rebuild — used by
     *  {@link #createCardBorder()} so each card no longer does its own
     *  O(n) storage scan to find its parent group's color. */
    private final Map<String, ProfileGroup> groupsById;

    public AccountCardPanel(RosterPlugin plugin, Account profile, RosterPanel parentPanel)
    {
        this(plugin, profile, parentPanel, Collections.emptyMap());
    }

    public AccountCardPanel(RosterPlugin plugin, Account profile, RosterPanel parentPanel,
                            Map<String, ProfileGroup> groupsById)
    {
        this.plugin = plugin;
        this.profile = profile;
        this.config = plugin.getConfig();
        this.parentPanel = parentPanel;
        this.groupsById = groupsById != null ? groupsById : Collections.emptyMap();
        boolean isSelected = profile.getId().equals(plugin.getSelectedAccountId());
        this.currentBackground = isSelected ? Theme.CARD_SELECTED : Theme.CARD_BACKGROUND;

        setLayout(new BorderLayout(0, 0));
        setBackground(currentBackground);
        setBorder(createCardBorder());
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        if (config.gridView())
        {
            GridAccountBuilder.build(this, plugin, profile, this::expandGridEdit);
            setPreferredSize(new Dimension(0, GridAccountBuilder.GRID_CARD_HEIGHT));
            setMaximumSize(new Dimension(Integer.MAX_VALUE, GridAccountBuilder.GRID_CARD_HEIGHT));
        }
        else
        {
            setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.CARD_HEIGHT));
            buildCard(parentPanel);
        }
        setupMouseListeners();
    }

    private javax.swing.border.Border createCardBorder()
    {
        String gid = profile.getGroupId();
        if (gid != null)
        {
            // Prefer the pre-resolved map; fall back to storage only when this card
            // was constructed via the legacy single-arg constructor (e.g. dialogs).
            ProfileGroup group = groupsById.get(gid);
            if (group == null)
            {
                group = plugin.getAccountStorage().getGroup(gid);
            }
            if (group != null)
            {
                Color catColor = Theme.parseColor(group.getColor());
                if (catColor != null)
                {
                    return BorderFactory.createCompoundBorder(
                        BorderFactory.createMatteBorder(0, Theme.CATEGORY_BORDER_WIDTH, 0, 0, catColor),
                        BorderFactory.createLineBorder(Theme.CARD_BORDER, 1)
                    );
                }
            }
        }
        return BorderFactory.createLineBorder(Theme.CARD_BORDER, 1);
    }

    private JPanel infoPanelHolder;

    private void buildCard(RosterPanel parentPanel)
    {
        headerPanel = new JPanel(new BorderLayout(Theme.SPACING_MD, 0));
        headerPanel.setOpaque(false);
        headerPanel.setBorder(new EmptyBorder(Theme.SPACING_MD, Theme.SPACING_LG, Theme.SPACING_MD, Theme.SPACING_LG));

        // Wrap the info panel so refreshDynamicState() can replace it in place
        // without disturbing the action buttons (which carry their own listeners).
        infoPanelHolder = new JPanel(new BorderLayout());
        infoPanelHolder.setOpaque(false);
        infoPanelHolder.add(createInfoPanel(), BorderLayout.CENTER);
        headerPanel.add(infoPanelHolder, BorderLayout.CENTER);
        headerPanel.add(createActionButtons(), BorderLayout.EAST);

        add(headerPanel, BorderLayout.NORTH);

        expansionHandler = new CardExpansionHandler(plugin, profile, parentPanel, this, headerPanel);
        JPanel formPanel = expansionHandler.createFormPanel();
        formPanel.setVisible(false);
        add(formPanel, BorderLayout.CENTER);
    }

    /**
     * Recompute the parts of this card that depend on transient plugin state
     * (selected highlight, online dot, last-online label) without rebuilding
     * the full panel. Called by {@link RosterPanel#refreshAccount(String)} after
     * {@code selectAccount} or {@code stampLastOnline}.
     *
     * <p>Grid cards are rebuilt by {@code GridAccountBuilder}, which composes the
     * whole card body in a single call — for those we fall back to a full panel
     * rebuild via the caller (which handles a missing card id the same way).
     * No-op when the card is currently expanded for editing.
     */
    public void refreshDynamicState()
    {
        if (config.gridView() || infoPanelHolder == null)
        {
            // Grid cards aren't covered by the holder pattern. Punt to a full
            // rebuild — incremental work isn't worth the complexity for the
            // compact view. The caller will catch this via the cardsByAccountId
            // miss path on the next refresh.
            if (plugin.getPanel() != null) plugin.getPanel().rebuild();
            return;
        }
        if (expansionHandler != null && expansionHandler.isExpanded())
        {
            // Don't rebuild the info panel while the user is editing — would
            // visually flicker the form open beneath them.
            return;
        }
        boolean isSelected = profile.getId().equals(plugin.getSelectedAccountId());
        currentBackground = isSelected ? Theme.CARD_SELECTED : Theme.CARD_BACKGROUND;
        setBackground(currentBackground);

        infoPanelHolder.removeAll();
        infoPanelHolder.add(createInfoPanel(), BorderLayout.CENTER);
        infoPanelHolder.revalidate();
        infoPanelHolder.repaint();
    }

    private JPanel createInfoPanel()
    {
        JPanel infoPanel = new JPanel(new GridBagLayout());
        infoPanel.setOpaque(false);

        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = 0;
        gbc.gridy = 0;
        gbc.anchor = GridBagConstraints.WEST;
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.weightx = 1.0;

        // Display name — determine what to show based on privacy settings
        String displayName = AccountCardHelper.resolveDisplayName(profile, config);
        String loggedIn = plugin.getLoggedInDisplayName();
        // Prefer the learned in-game character name; the display name (alias or
        // login email) only matches by coincidence when the alias equals the
        // character name.
        String matchName = profile.getCharacterName() != null
            ? profile.getCharacterName()
            : profile.getDisplayName();
        boolean isOnline = loggedIn != null && loggedIn.equalsIgnoreCase(matchName);

        // Always render in a row so we can fit the type badge alongside the name.
        JPanel nameRow = new JPanel(new FlowLayout(FlowLayout.LEFT, Theme.SPACING_SM, 0));
        nameRow.setOpaque(false);
        if (isOnline)
        {
            nameRow.add(AccountCardHelper.createOnlineDot());
        }
        // Truncate slightly shorter to leave room for the badge — keeps the
        // common case (online + Main placeholder) from clipping.
        int nameMax = isOnline ? 13 : 15;
        nameRow.add(AccountCardHelper.createTruncatingLabel(displayName, Theme.TEXT_PRIMARY,
            Theme.fontBold(getFont(), Theme.FONT_SIZE_HEADING), nameMax));
        nameRow.add(createTypeBadge());
        infoPanel.add(nameRow, gbc);
        gbc.gridy++;

        // Username (shown if not hidden and different from display name)
        if (!config.hideLogin())
        {
            String username = profile.getUsername();
            if (username != null && !username.equals(displayName))
            {
                infoPanel.add(AccountCardHelper.createTruncatingLabel(username, Theme.TEXT_SECONDARY,
                    Theme.fontRegular(getFont(), Theme.FONT_SIZE_HEADING), 25), gbc);
                gbc.gridy++;
            }
        }

        // Notes preview
        if (!config.hideNotes())
        {
            AccountMetadata meta = profile.getMetadata();
            if (meta != null && meta.getNotes() != null && !meta.getNotes().isEmpty())
            {
                String notes = meta.getNotes();
                JLabel notesLabel = AccountCardHelper.createTruncatingLabel(notes, Theme.TEXT_SECONDARY,
                    Theme.fontRegular(getFont(), Theme.FONT_SIZE_BODY), 22);
                notesLabel.setToolTipText("<html><body style='width: 200px'>" + AccountCardHelper.escapeHtml(notes) + "</body></html>");
                infoPanel.add(notesLabel, gbc);
                gbc.gridy++;
            }
        }

        // Last-online stamp (suppressed while the account is currently logged in —
        // the green online dot already conveys that, and "just now" would be misleading
        // once they've been online for hours).
        if (!isOnline && !config.hideLastOnline())
        {
            AccountMetadata meta = profile.getMetadata();
            if (meta != null && meta.getLastOnlineAt() != null)
            {
                String relative = AccountCardHelper.formatTimeAgo(meta.getLastOnlineAt());
                if (relative != null)
                {
                    JLabel lastOnlineLabel = new JLabel(relative);
                    lastOnlineLabel.setForeground(Theme.TEXT_MUTED);
                    lastOnlineLabel.setFont(Theme.fontRegular(getFont(), Theme.FONT_SIZE_TINY));
                    lastOnlineLabel.setToolTipText("Last seen logged in on this client");
                    infoPanel.add(lastOnlineLabel, gbc);
                }
            }
        }

        return infoPanel;
    }

    /**
     * Creates the clickable type badge that appears beside the account name.
     * Clicking it opens a popup that lets the user change the account's type
     * without opening the full edit form.
     */
    private AccountTypeBadge createTypeBadge()
    {
        AccountType current = (profile.getMetadata() != null
            && profile.getMetadata().getAccountType() != null)
            ? profile.getMetadata().getAccountType()
            : AccountType.MAIN;

        return new AccountTypeBadge(current, newType ->
        {
            AccountMetadata meta = profile.getMetadata();
            if (meta == null)
            {
                meta = AccountMetadata.createDefault();
                profile.setMetadata(meta);
            }
            meta.setAccountType(newType);
            plugin.getAccountStorage().saveAccount(profile);
            // Only this card's badge changed — refresh it in place instead of
            // tearing down the whole panel. (Grid view falls back to a full
            // rebuild inside refreshDynamicState.)
            if (parentPanel != null)
            {
                parentPanel.refreshAccount(profile.getId());
            }
            else
            {
                plugin.getPanel().rebuild();
            }
        });
    }

    private JPanel createActionButtons()
    {
        JPanel rightPanel = new JPanel();
        rightPanel.setLayout(new BoxLayout(rightPanel, BoxLayout.Y_AXIS));
        rightPanel.setOpaque(false);
        rightPanel.add(createEditButton());
        rightPanel.add(createMenuButton());
        return rightPanel;
    }

    private JButton createEditButton()
    {
        JButton button = new JButton("\u270E");
        button.setBackground(Theme.CARD_BACKGROUND);
        button.setForeground(Theme.TEXT_PRIMARY);
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setPreferredSize(new Dimension(Theme.MENU_BUTTON_SIZE, Theme.MENU_BUTTON_SIZE));
        button.setFont(button.getFont().deriveFont(14f));
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setToolTipText("Edit account");
        button.addActionListener(e -> { if (expansionHandler != null) expansionHandler.toggleExpanded(); });
        button.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e) { button.setBackground(Theme.CARD_HOVER); }

            @Override
            public void mouseExited(MouseEvent e) { button.setBackground(hovered ? Theme.CARD_HOVER : getBaseBackground()); }
        });
        return button;
    }

    private JButton createMenuButton()
    {
        JButton button = new JButton("\u22EE");
        button.setBackground(Theme.CARD_BACKGROUND);
        button.setForeground(Theme.TEXT_PRIMARY);
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setPreferredSize(new Dimension(Theme.MENU_BUTTON_SIZE, Theme.MENU_BUTTON_SIZE));
        button.setFont(button.getFont().deriveFont(16f));
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setToolTipText("More options");

        Runnable onExpand = () -> { if (expansionHandler != null) expansionHandler.expand(); };
        AccountCardActions actions = new AccountCardActions(plugin, profile, onExpand);
        // Build the menu on first click — constructing it eagerly added six
        // menu items + listeners per card per rebuild, for menus rarely opened.
        JPopupMenu[] menuRef = new JPopupMenu[1];
        button.addActionListener(e -> {
            if (menuRef[0] == null)
            {
                menuRef[0] = actions.createContextMenu();
            }
            menuRef[0].show(button, 0, button.getHeight());
        });

        button.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e) { button.setBackground(Theme.CARD_HOVER); }

            @Override
            public void mouseExited(MouseEvent e) { button.setBackground(hovered ? Theme.CARD_HOVER : getBaseBackground()); }
        });
        return button;
    }

    public boolean isExpanded()
    {
        if (gridEditMode) return true;
        return expansionHandler != null && expansionHandler.isExpanded();
    }

    public void expand()
    {
        if (config.gridView()) expandGridEdit();
        else if (expansionHandler != null) expansionHandler.expand();
    }

    public void collapse()
    {
        if (gridEditMode) collapseGridEdit();
        else if (expansionHandler != null) expansionHandler.collapse();
    }

    private void expandGridEdit()
    {
        if (gridEditMode) return;
        // Collapse any other expanded card first
        if (parentPanel != null)
        {
            parentPanel.collapseExpandedCard();
            parentPanel.setExpandedCard(this);
        }
        gridEditMode = true;

        // Replace grid content with inline edit form
        removeAll();
        setLayout(new BorderLayout(0, 0));
        setBackground(Theme.FORM_BACKGROUND);
        setCursor(Cursor.getDefaultCursor());

        InlineAccountForm editForm = new InlineAccountForm(plugin, profile, true, null);
        editForm.setOnSave(savedAccount -> {
            plugin.getAccountStorage().saveAccount(savedAccount);
            collapseGridEdit();
            plugin.getPanel().rebuild();
        });
        editForm.setOnCancel(this::collapseGridEdit);
        add(editForm, BorderLayout.CENTER);

        // Remove fixed height so the form can size naturally
        setPreferredSize(null);
        setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        editForm.focusUsernameField();
        AccountCardHelper.revalidateToWindow(this);
    }

    private void collapseGridEdit()
    {
        if (!gridEditMode) return;
        gridEditMode = false;
        if (parentPanel != null) parentPanel.setExpandedCard(null);
        // Just rebuild the whole panel — simpler than trying to restore grid card state
        plugin.getPanel().rebuild();
    }

    private void setupMouseListeners()
    {
        if (headerPanel != null)
        {
            headerPanel.addMouseListener(new MouseAdapter()
            {
                @Override
                public void mouseEntered(MouseEvent e) { hovered = true; animateBackground(Theme.CARD_HOVER); }

                @Override
                public void mouseExited(MouseEvent e) { hovered = false; animateBackground(getBaseBackground()); }

                @Override
                public void mouseClicked(MouseEvent e)
                {
                    if (e.getButton() == MouseEvent.BUTTON1 && e.getClickCount() == 1
                        && (expansionHandler == null || !expansionHandler.isExpanded()))
                    {
                        plugin.selectAccount(profile);
                    }
                }
            });
        }

        addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e) { hovered = true; animateBackground(Theme.CARD_HOVER); }

            @Override
            public void mouseExited(MouseEvent e) { hovered = false; animateBackground(getBaseBackground()); }

            @Override
            public void mouseClicked(MouseEvent e)
            {
                if (headerPanel == null && e.getButton() == MouseEvent.BUTTON1)
                {
                    if (e.getClickCount() == 2 && !gridEditMode)
                    {
                        expandGridEdit();
                    }
                    else if (e.getClickCount() == 1 && !gridEditMode)
                    {
                        plugin.selectAccount(profile);
                    }
                }
            }
        });
    }

    private Color getBaseBackground()
    {
        boolean isSelected = profile.getId().equals(plugin.getSelectedAccountId());
        return isSelected ? Theme.CARD_SELECTED : Theme.CARD_BACKGROUND;
    }

    private void animateBackground(Color target)
    {
        currentBackground = target;
        setBackground(target);
        repaint();
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.ImportDuplicateMode;
import com.mylosis.roster.storage.ExportResult;
import com.mylosis.roster.storage.ImportExportService;
import com.mylosis.roster.storage.ImportResult;
import com.mylosis.roster.storage.AccountStorage;
import com.mylosis.roster.ui.components.ExpandingMenuButton;
import com.mylosis.roster.ui.components.IconButton;
import com.mylosis.roster.ui.components.Icons;
import com.mylosis.roster.ui.components.NotificationToast;
import com.mylosis.roster.ui.components.Theme;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.function.BiConsumer;

/**
 * Builds the footer section of the Roster panel.
 * Contains profile count, clear-all button, and import/export menu.
 */
@Slf4j
public class PanelFooterBuilder
{
    private final RosterPlugin plugin;
    private final AccountStorage storage;
    private final BiConsumer<String, NotificationToast.Type> showNotification;
    private final Runnable onRebuild;

    public PanelFooterBuilder(RosterPlugin plugin, BiConsumer<String, NotificationToast.Type> showNotification,
                              Runnable onRebuild)
    {
        this.plugin = plugin;
        this.storage = plugin.getAccountStorage();
        this.showNotification = showNotification;
        this.onRebuild = onRebuild;
    }

    public JPanel build(JLabel accountCountLabel)
    {
        JPanel footer = new JPanel(new BorderLayout(Theme.SPACING_SM, Theme.SPACING_SM));
        footer.setBackground(Theme.BACKGROUND);
        footer.setBorder(new EmptyBorder(Theme.SPACING_LG, 0, 0, 0));

        footer.add(accountCountLabel, BorderLayout.WEST);

        JPanel rightPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, Theme.SPACING_XS, 0));
        rightPanel.setOpaque(false);
        rightPanel.add(createViewToggleButton());
        rightPanel.add(createImportExportMenu());
        rightPanel.add(createClearAllButton());

        footer.add(rightPanel, BorderLayout.EAST);
        return footer;
    }

    private IconButton createViewToggleButton()
    {
        boolean isGrid = plugin.getConfig().gridView();
        String icon = isGrid ? Icons.LIST : Icons.GRID;
        String tooltip = isGrid ? "Switch to list view" : "Switch to grid view";
        IconButton button = new IconButton(icon, tooltip);
        button.addActionListener(e -> {
            net.runelite.client.config.ConfigManager configManager = plugin.getConfigManager();
            boolean current = plugin.getConfig().gridView();
            boolean next = !current;
            configManager.setConfiguration(RosterConfig.CONFIG_GROUP, "gridView", next);
            // Update button icon and tooltip to reflect new state
            button.updateIcon(next ? Icons.LIST : Icons.GRID);
            button.setToolTipText(next ? "Switch to list view" : "Switch to grid view");
        });
        return button;
    }

    private IconButton createClearAllButton()
    {
        IconButton button = new IconButton(Icons.DELETE, "Clear...");
        JPopupMenu clearMenu = new JPopupMenu();

        JMenuItem clearProfiles = new JMenuItem("Clear All Accounts");
        clearProfiles.addActionListener(e -> confirmClear("accounts"));
        clearMenu.add(clearProfiles);

        JMenuItem clearCategories = new JMenuItem("Clear All Categories");
        clearCategories.addActionListener(e -> confirmClear("categories"));
        clearMenu.add(clearCategories);

        clearMenu.addSeparator();

        JMenuItem clearBoth = new JMenuItem("Clear Everything");
        clearBoth.setForeground(Theme.BUTTON_DANGER);
        clearBoth.addActionListener(e -> confirmClear("both"));
        clearMenu.add(clearBoth);

        button.addActionListener(e -> clearMenu.show(button, 0, -clearMenu.getPreferredSize().height));
        return button;
    }

    private ExpandingMenuButton createImportExportMenu()
    {
        ExpandingMenuButton menu = new ExpandingMenuButton(Icons.CLIPBOARD, "Export/Import accounts");
        menu.addMenuItem("Import from Clipboard", this::doImport);
        menu.addMenuItem("Export to Clipboard", this::doExport);
        return menu;
    }

    private void doExport()
    {
        ImportExportService service = plugin.getImportExportService();
        ExportResult result = service.exportToClipboard();

        if (result.success)
        {
            showNotification.accept("Copied " + result.accountCount + " accounts, " + result.groupCount + " categories",
                NotificationToast.Type.SUCCESS);
        }
        else
        {
            showNotification.accept("Copy failed: " + result.error, NotificationToast.Type.ERROR);
        }
    }

    private void doImport()
    {
        ImportExportService service = plugin.getImportExportService();
        ImportDuplicateMode duplicateMode = plugin.getConfig().importDuplicateMode();
        ImportResult result = service.importFromClipboard(false, duplicateMode);

        log.info("Import result: success={}, added={}, skipped={}, updated={}, error={}",
            result.success, result.accountsAdded, result.accountsSkipped, result.accountsUpdated, result.error);

        if (result.success)
        {
            NotificationToast.Type type = result.hasChanges() ? NotificationToast.Type.SUCCESS : NotificationToast.Type.WARNING;
            showNotification.accept(result.getDetailedMessage(), type);
            if (result.hasChanges()) onRebuild.run();
        }
        else
        {
            showNotification.accept("Import failed: " + result.error, NotificationToast.Type.ERROR);
        }
    }

    private void confirmClear(String mode)
    {
        int accountCount = storage.getAccounts().size();
        int groupCount = storage.getGroups().size();

        String message;
        String title;
        switch (mode)
        {
            case "accounts":
                if (accountCount == 0) { showNotification.accept("No accounts to clear", NotificationToast.Type.INFO); return; }
                message = "Delete all " + accountCount + " accounts?\n\nThis cannot be undone.";
                title = "Clear Accounts";
                break;
            case "categories":
                if (groupCount == 0) { showNotification.accept("No categories to clear", NotificationToast.Type.INFO); return; }
                message = "Delete all " + groupCount + " categories?\nProfiles will be moved to Uncategorized.";
                title = "Clear Categories";
                break;
            default:
                if (accountCount == 0 && groupCount == 0) { showNotification.accept("Nothing to clear", NotificationToast.Type.INFO); return; }
                message = "Delete all " + accountCount + " accounts and " + groupCount + " categories?\n\nThis cannot be undone.";
                title = "Clear Everything";
                break;
        }

        int result = JOptionPane.showConfirmDialog(
            SwingUtilities.getWindowAncestor(plugin.getPanel()),
            message, title, JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE
        );

        if (result == JOptionPane.YES_OPTION)
        {
            if ("accounts".equals(mode) || "both".equals(mode))
            {
                storage.deleteAllProfiles();
            }
            if ("categories".equals(mode) || "both".equals(mode))
            {
                storage.deleteAllGroups();
            }
            showNotification.accept("Cleared " + mode, NotificationToast.Type.SUCCESS);
            onRebuild.run();
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.storage.AccountStorage;
import com.mylosis.roster.ui.components.NotificationToast;
import com.mylosis.roster.ui.components.Theme;
import com.mylosis.roster.ui.dnd.DragDropManager;
import com.mylosis.roster.ui.dnd.DragOverlay;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.HashMap;
import java.util.Map;

/**
 * Main panel for the Roster plugin.
 * Orchestrates header, form, profile list, footer, and notification components.
 */
@Slf4j
public class RosterPanel extends PluginPanel
{
    private final RosterPlugin plugin;
    private final AccountStorage storage;

    @Getter
    private final DragDropManager dragDropManager;
    private final AccountListBuilder listBuilder;
    @Getter
    private final PanelFormManager formManager;

    private JPanel profileListPanel;
    private JScrollPane scrollPane;
    private final JLayeredPane layeredPane;
    private final DragOverlay dragOverlay;
    private JPanel notificationPanel;
    private JLabel accountCountLabel;

    private String searchFilter = "";

    @Setter
    private AccountCardPanel expandedCard = null;

    /**
     * Live id→card lookup populated during each rebuild. Lets callers like
     * {@link #refreshCard(String)} update a single visible card in place instead
     * of forcing a full panel rebuild for trivial state changes (selection
     * highlight, last-online timestamp). Stale entries (e.g. a deleted account)
     * naturally drop out on the next rebuild; missing entries fall back to a
     * full rebuild via {@link #refreshAccount(String)}.
     */
    private final Map<String, AccountCardPanel> cardsByAccountId = new HashMap<>();

    public RosterPanel(RosterPlugin plugin)
    {
        // Disable PluginPanel's default outer JScrollPane wrap — we manage our own
        // scrolling via the inner scrollPane built in buildContentPanel(). With the
        // outer wrap in place wheel events were swallowed by the inner viewport
        // (which never needed to scroll, since it sized to its content), leaving
        // the user with a dead scroll wheel.
        super(false);
        this.plugin = plugin;
        this.storage = plugin.getAccountStorage();
        this.dragDropManager = new DragDropManager(plugin, this);
        this.dragOverlay = dragDropManager.getOverlay();
        this.listBuilder = new AccountListBuilder(plugin, this, dragDropManager);
        this.formManager = new PanelFormManager(plugin, this::rebuild, this::doRevalidate);

        setLayout(new BorderLayout());
        setBackground(Theme.BACKGROUND);

        layeredPane = new JLayeredPane();
        layeredPane.setLayout(new OverlayLayout(layeredPane));

        JPanel contentPanel = buildContentPanel();
        layeredPane.add(contentPanel, JLayeredPane.DEFAULT_LAYER);

        notificationPanel = buildNotificationPanel();
        layeredPane.add(notificationPanel, JLayeredPane.POPUP_LAYER);

        layeredPane.addComponentListener(new java.awt.event.ComponentAdapter()
        {
            @Override
            public void componentResized(java.awt.event.ComponentEvent e)
            {
                repositionNotificationPanel();
            }
        });

        dragOverlay.setVisible(false);
        layeredPane.add(dragOverlay, JLayeredPane.DRAG_LAYER);

        add(layeredPane, BorderLayout.CENTER);
        rebuild();
    }

    private JPanel buildContentPanel()
    {
        JPanel contentPanel = new JPanel(new BorderLayout());
        contentPanel.setBackground(Theme.BACKGROUND);
        contentPanel.setBorder(new EmptyBorder(Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM));

        // Header with search and action buttons
        PanelHeaderBuilder headerBuilder = new PanelHeaderBuilder();
        JPanel headerPanel = headerBuilder.build(
            filter -> {
                // The debounce can fire with unchanged text (type then delete
                // within the window) — don't pay a full rebuild for a no-op.
                if (!filter.equals(searchFilter))
                {
                    searchFilter = filter;
                    rebuild();
                }
            },
            () -> formManager.toggleAddProfileForm(this::collapseExpandedCardOnly),
            () -> formManager.toggleAddCategoryForm(this::collapseExpandedCardOnly),
            () -> plugin.getConfig().sortKey(),
            newKey -> {
                plugin.getConfigManager().setConfiguration(
                    RosterConfig.CONFIG_GROUP, "sortKey", newKey);
                // onConfigChanged will trigger the rebuild
            }
        );

        // Attach form panels below action buttons
        JPanel headerWithForms = new JPanel();
        headerWithForms.setLayout(new BoxLayout(headerWithForms, BoxLayout.Y_AXIS));
        headerWithForms.setBackground(Theme.BACKGROUND);
        headerWithForms.add(headerPanel);
        headerWithForms.add(formManager.getAddProfileFormPanel());
        headerWithForms.add(formManager.getAddCategoryFormPanel());

        contentPanel.add(headerWithForms, BorderLayout.NORTH);

        // Scrollable profile list
        profileListPanel = new JPanel();
        profileListPanel.setLayout(new BoxLayout(profileListPanel, BoxLayout.Y_AXIS));
        profileListPanel.setBackground(Theme.BACKGROUND);

        scrollPane = new JScrollPane(profileListPanel);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setBorder(null);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        scrollPane.setBackground(Theme.BACKGROUND);
        scrollPane.getViewport().setBackground(Theme.BACKGROUND);
        contentPanel.add(scrollPane, BorderLayout.CENTER);

        // Footer with count and actions
        accountCountLabel = new JLabel("0 Accounts");
        accountCountLabel.setForeground(Theme.TEXT_SECONDARY);
        accountCountLabel.setFont(Theme.fontRegular(accountCountLabel.getFont(), Theme.FONT_SIZE_SMALL));

        PanelFooterBuilder footerBuilder = new PanelFooterBuilder(plugin, this::showNotification, this::rebuild);
        contentPanel.add(footerBuilder.build(accountCountLabel), BorderLayout.SOUTH);

        return contentPanel;
    }

    private JPanel buildNotificationPanel()
    {
        JPanel panel = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0))
        {
            @Override
            public boolean isOptimizedDrawingEnabled()
            {
                return false;
            }
        };
        panel.setOpaque(false);
        panel.setAlignmentX(0f);
        panel.setAlignmentY(0.5f);
        panel.setMaximumSize(new Dimension(0, 0));
        return panel;
    }

    public void rebuild()
    {
        // Create a fresh panel to avoid stale layout caches from BoxLayout
        JPanel newListPanel = new JPanel();
        newListPanel.setLayout(new BoxLayout(newListPanel, BoxLayout.Y_AXIS));
        newListPanel.setBackground(Theme.BACKGROUND);

        // Clear the card index — the rebuild below will repopulate it as each
        // AccountCardPanel is created. Old card references are dropped here so
        // they can be GC'd along with the discarded list panel.
        cardsByAccountId.clear();

        int[] counts = listBuilder.rebuild(newListPanel, searchFilter);
        updateProfileCount(counts[0], counts[1]);

        // Swap the viewport to the fresh panel — forces complete layout recalculation
        profileListPanel = newListPanel;
        scrollPane.setViewportView(profileListPanel);
        scrollPane.getVerticalScrollBar().setValue(0);

        // Scope the revalidate to the scrollpane subtree. The previous version
        // walked all the way to the root window — overkill for a sidebar redraw,
        // and on Windows it visibly flickered other RuneLite panels. Validating
        // the viewport then the scrollpane is enough: the viewport view changed,
        // and the scrollpane is the boundary of layout invalidation for our panel.
        scrollPane.getViewport().revalidate();
        scrollPane.revalidate();
        scrollPane.repaint();
    }

    private void updateProfileCount(int filtered, int total)
    {
        if (filtered == total)
        {
            accountCountLabel.setText(total + " Account" + (total != 1 ? "s" : ""));
        }
        else
        {
            accountCountLabel.setText(filtered + " / " + total + " Accounts");
        }
    }

    /**
     * Collapse any currently expanded profile card and hide add form.
     */
    public void collapseExpandedCard()
    {
        collapseExpandedCardOnly();
        formManager.hideAddForm();
    }

    private void collapseExpandedCardOnly()
    {
        if (expandedCard != null)
        {
            expandedCard.collapse();
            expandedCard = null;
        }
    }

    public void showNotification(String message, NotificationToast.Type type)
    {
        NotificationToast toast = new NotificationToast(message, type, 3000);
        // Stop the previous toast's fade/dismiss timers before discarding it —
        // removeAll() alone leaves them firing 16ms repaints against a
        // parentless component for up to ~3.5s.
        for (Component c : notificationPanel.getComponents())
        {
            if (c instanceof NotificationToast)
            {
                ((NotificationToast) c).stopTimers();
            }
        }
        notificationPanel.removeAll();
        notificationPanel.add(toast);
        notificationPanel.revalidate();
        SwingUtilities.invokeLater(this::repositionNotificationPanel);
    }

    private void repositionNotificationPanel()
    {
        if (notificationPanel.getComponentCount() == 0)
        {
            notificationPanel.setBounds(0, 0, 0, 0);
            return;
        }

        int panelWidth = layeredPane.getWidth();
        int panelHeight = layeredPane.getHeight();
        notificationPanel.setSize(panelWidth, 100);
        notificationPanel.doLayout();
        Dimension pref = notificationPanel.getPreferredSize();
        int y = panelHeight - pref.height - 50;
        notificationPanel.setBounds(0, y, panelWidth, pref.height + 20);
        notificationPanel.repaint();
    }

    private void doRevalidate()
    {
        revalidate();
        repaint();
    }

    /**
     * Called by {@link AccountListBuilder} and {@link CategoryPanel} as each card is
     * inserted into the rebuilt list. Should not be called from elsewhere.
     */
    public void registerCard(String accountId, AccountCardPanel card)
    {
        if (accountId != null && card != null)
        {
            cardsByAccountId.put(accountId, card);
        }
    }

    /**
     * Refreshes a single card's mutable visual state (selected-highlight, online
     * indicator, last-online label) without rebuilding the panel. Falls back to a
     * full {@link #rebuild()} if the card isn't in the live index — e.g. because
     * it's currently filtered out by search, or the account was deleted.
     */
    public void refreshAccount(String accountId)
    {
        if (accountId == null)
        {
            return;
        }
        AccountCardPanel card = cardsByAccountId.get(accountId);
        if (card == null)
        {
            // Not visible. If the account exists but is merely filtered out by
            // the active search, a rebuild would produce the identical view —
            // skip it (login/logout events during a search hit this path).
            if (!searchFilter.isEmpty())
            {
                com.mylosis.roster.model.Account account = storage.getProfile(accountId);
                if (account != null && !account.getSearchHaystack().contains(searchFilter))
                {
                    return;
                }
            }
            // Genuinely unknown card — full rebuild is the safe fallback.
            rebuild();
            return;
        }
        card.refreshDynamicState();
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.model.SortKey;
import com.mylosis.roster.ui.components.SearchBar;
import com.mylosis.roster.ui.components.Theme;
import lombok.Getter;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Builds the header section of the Roster panel.
 * Contains title, version badge, search bar, and action buttons
 * (+ Account, + Category, and the v1.1 sort selector).
 */
public class PanelHeaderBuilder
{
    @Getter
    private SearchBar searchBar;

    /**
     * Create the full header panel.
     *
     * @param onSearchChanged callback fired when the user types in the search bar
     * @param onAddAccount    callback for the "+ Account" button
     * @param onAddCategory   callback for the "+ Category" button
     * @param currentSortKey  supplier for the live SortKey (read each time the menu opens
     *                        so the check mark reflects the active value)
     * @param onSortChanged   callback when the user picks a new SortKey
     */
    public JPanel build(Consumer<String> onSearchChanged,
                        Runnable onAddAccount,
                        Runnable onAddCategory,
                        Supplier<SortKey> currentSortKey,
                        Consumer<SortKey> onSortChanged)
    {
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(Theme.BACKGROUND);
        header.setBorder(BorderFactory.createEmptyBorder(0, 0, Theme.SPACING_LG, 0));

        header.add(createTitleRow());
        header.add(Box.createVerticalStrut(Theme.SPACING_MD));

        searchBar = createSearchBar(onSearchChanged);
        header.add(searchBar);
        header.add(Box.createVerticalStrut(Theme.SPACING_MD));

        header.add(createActionButtonsRow(onAddAccount, onAddCategory, currentSortKey, onSortChanged));

        return header;
    }

    private JPanel createTitleRow()
    {
        JPanel titleRow = new JPanel(new BorderLayout());
        titleRow.setBackground(Theme.BACKGROUND);
        titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel titleLabel = new JLabel("Roster");
        titleLabel.setForeground(Theme.TEXT_PRIMARY);
        titleLabel.setFont(Theme.fontBold(titleLabel.getFont(), Theme.FONT_SIZE_TITLE));
        titleRow.add(titleLabel, BorderLayout.WEST);

        JLabel versionLabel = new JLabel("v" + Theme.VERSION);
        versionLabel.setForeground(Theme.TEXT_MUTED);
        versionLabel.setFont(Theme.fontRegular(versionLabel.getFont(), Theme.FONT_SIZE_TINY));
        titleRow.add(versionLabel, BorderLayout.EAST);

        return titleRow;
    }

    private SearchBar createSearchBar(Consumer<String> onSearchChanged)
    {
        SearchBar bar = new SearchBar();
        bar.setPlaceholder("Filter...");
        bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        bar.setAlignmentX(Component.LEFT_ALIGNMENT);
        bar.setOnSearchChanged(onSearchChanged::accept);
        return bar;
    }

    private JPanel createActionButtonsRow(Runnable onAddAccount, Runnable onAddCategory,
                                          Supplier<SortKey> currentSortKey,
                                          Consumer<SortKey> onSortChanged)
    {
        JPanel buttonRow = new JPanel(new GridBagLayout());
        buttonRow.setBackground(Theme.BACKGROUND);
        buttonRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT + 4));
        buttonRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        GridBagConstraints gbc = new GridBagConstraints();
        gbc.fill = GridBagConstraints.BOTH;
        gbc.gridy = 0;

        gbc.gridx = 0;
        gbc.weightx = 0.55;
        gbc.insets = new Insets(0, 0, 0, Theme.SPACING_XS);
        buttonRow.add(createActionButton("+ Account", "Add a new account", onAddAccount), gbc);

        gbc.gridx = 1;
        gbc.weightx = 0.30;
        gbc.insets = new Insets(0, 0, 0, Theme.SPACING_XS);
        buttonRow.add(createActionButton("+ Category", "Add category", onAddCategory), gbc);

        gbc.gridx = 2;
        gbc.weightx = 0.15;
        gbc.insets = new Insets(0, 0, 0, 0);
        buttonRow.add(createSortButton(currentSortKey, onSortChanged), gbc);

        return buttonRow;
    }

    private JButton createActionButton(String text, String tooltip, Runnable onClick)
    {
        JButton button = new JButton(text);
        button.setBackground(Theme.BUTTON_SECONDARY);
        button.setForeground(Theme.TEXT_PRIMARY);
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setFont(Theme.fontRegular(button.getFont(), Theme.FONT_SIZE_BODY));
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setToolTipText(tooltip);
        button.addActionListener(e -> onClick.run());
        button.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseEntered(java.awt.event.MouseEvent e)
            {
                button.setBackground(Theme.BUTTON_SECONDARY_HOVER);
            }

            @Override
            public void mouseExited(java.awt.event.MouseEvent e)
            {
                button.setBackground(Theme.BUTTON_SECONDARY);
            }
        });
        return button;
    }

    /**
     * Compact icon button that opens a popup menu listing every {@link SortKey},
     * with the currently-active key checkmarked. Picking an option fires the
     * supplied {@code onSortChanged} callback (which writes config + rebuilds).
     */
    private JButton createSortButton(Supplier<SortKey> currentSortKey,
                                     Consumer<SortKey> onSortChanged)
    {
        JButton button = new JButton("⇵"); // ⇅
        button.setBackground(Theme.BUTTON_SECONDARY);
        button.setForeground(Theme.TEXT_PRIMARY);
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setFont(Theme.fontBold(button.getFont(), Theme.FONT_SIZE_BODY));
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setToolTipText("Sort accounts");
        button.addActionListener(e -> showSortMenu(button, currentSortKey, onSortChanged));
        button.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseEntered(java.awt.event.MouseEvent e) { button.setBackground(Theme.BUTTON_SECONDARY_HOVER); }

            @Override
            public void mouseExited(java.awt.event.MouseEvent e) { button.setBackground(Theme.BUTTON_SECONDARY); }
        });
        return button;
    }

    private void showSortMenu(JButton anchor, Supplier<SortKey> currentSortKey,
                              Consumer<SortKey> onSortChanged)
    {
        SortKey active = currentSortKey.get();
        JPopupMenu menu = new JPopupMenu();
        menu.setBackground(Theme.BACKGROUND_DARKER);
        menu.setBorder(BorderFactory.createLineBorder(Theme.CARD_BORDER, 1));

        for (SortKey key : SortKey.values())
        {
            JMenuItem item = new JMenuItem(key.getLabel());
            item.setBackground(Theme.BACKGROUND_DARKER);
            item.setForeground(key == active ? Theme.ACCENT_ORANGE : Theme.TEXT_PRIMARY);
            item.setFont(key == active
                ? Theme.fontBold(item.getFont(), Theme.FONT_SIZE_SMALL)
                : Theme.fontRegular(item.getFont(), Theme.FONT_SIZE_SMALL));
            item.setBorder(new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM));
            // Use a leading check glyph for the active item so it reads as a state, not a button
            if (key == active)
            {
                item.setText("✓ " + key.getLabel());
            }
            else
            {
                item.setText("    " + key.getLabel());
            }
            item.addActionListener(e -> onSortChanged.accept(key));
            menu.add(item);
        }
        menu.show(anchor, 0, anchor.getHeight());
    }
}

package com.mylosis.roster.ui.components;

import com.mylosis.roster.model.AccountType;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Consumer;

/**
 * Small clickable badge representing an {@link AccountType}, rendered with
 * the actual OSRS sprites from the wiki:
 *
 * <ul>
 *   <li>The six Ironman variants (Ironman, HCIM, UIM, GIM, UGIM) use the
 *       official in-game chat badges.</li>
 *   <li>Main, Skiller, and Pure are not official in-game account types,
 *       so we use community-recognisable item/skill icons: a Bronze sword
 *       for Main, a Bronze pickaxe for Skiller, and a Granite maul for Pure.</li>
 * </ul>
 *
 * Clicking opens a {@link JPopupMenu} listing all 8 types with their
 * matching sprite icons. Selecting one invokes the supplied callback.
 *
 * Resources live under {@code /com/mylosis/roster/badges/}.
 */
@Slf4j
public class AccountTypeBadge extends JComponent
{
    public static final int DEFAULT_SIZE = 20;

    private static final String RESOURCE_BASE = "/com/mylosis/roster/badges/";

    private static final Map<AccountType, String> RESOURCE = new EnumMap<>(AccountType.class);
    static
    {
        RESOURCE.put(AccountType.MAIN,                   "main.png");
        RESOURCE.put(AccountType.IRONMAN,                "ironman.png");
        RESOURCE.put(AccountType.HARDCORE_IRONMAN,       "hcim.png");
        RESOURCE.put(AccountType.ULTIMATE_IRONMAN,       "uim.png");
        RESOURCE.put(AccountType.GROUP_IRONMAN,          "gim.png");
        RESOURCE.put(AccountType.UNRANKED_GROUP_IRONMAN, "ugim.png");
        RESOURCE.put(AccountType.SKILLER,                "skiller.png");
        RESOURCE.put(AccountType.PURE,                   "pure.png");
    }

    /** Class-loaded once; image is cheap to re-use across cards/popovers. */
    private static final Map<AccountType, BufferedImage> CACHE = new EnumMap<>(AccountType.class);

    private static BufferedImage iconFor(AccountType t)
    {
        if (t == null)
        {
            return null;
        }
        BufferedImage cached = CACHE.get(t);
        if (cached != null)
        {
            // MISSING means a previous load failed — report "no icon" so the
            // caller paints the same grey-dot fallback it always painted.
            return cached == MISSING ? null : cached;
        }
        String resource = RESOURCE.get(t);
        if (resource == null)
        {
            return null;
        }
        try
        {
            BufferedImage img = ImageUtil.loadImageResource(AccountTypeBadge.class, RESOURCE_BASE + resource);
            CACHE.put(t, img);
            return img;
        }
        catch (Exception e)
        {
            // Negative-cache the failure: paintComponent calls iconFor on
            // every repaint, and an uncached miss meant re-attempting the
            // resource load (and swallowing a fresh exception) per paint.
            // MISSING is non-null so the cache hit short-circuits; painting
            // treats it as "no icon" and draws the grey-dot fallback.
            CACHE.put(t, MISSING);
            log.warn("Failed to load badge icon {}", resource, e);
            return null;
        }
    }

    /** Sentinel for "load failed" — see iconFor. */
    private static final BufferedImage MISSING = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);

    private AccountType type;
    private final int size;
    private final Consumer<AccountType> onChange;

    public AccountTypeBadge(AccountType type, Consumer<AccountType> onChange)
    {
        this(type, DEFAULT_SIZE, onChange);
    }

    public AccountTypeBadge(AccountType type, int size, Consumer<AccountType> onChange)
    {
        this.type = type != null ? type : AccountType.MAIN;
        this.size = size;
        this.onChange = onChange;

        Dimension dim = new Dimension(size, size);
        setPreferredSize(dim);
        setMaximumSize(dim);
        setMinimumSize(dim);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setToolTipText(this.type.getDisplayName() + " — click to change");
        setOpaque(false);

        addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                if (e.getButton() == MouseEvent.BUTTON1)
                {
                    showPicker();
                    e.consume();
                }
            }
        });
    }

    public void setType(AccountType newType)
    {
        this.type = newType != null ? newType : AccountType.MAIN;
        setToolTipText(this.type.getDisplayName() + " — click to change");
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        BufferedImage icon = iconFor(type);
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        g2.setRenderingHint(RenderingHints.KEY_RENDERING,      RenderingHints.VALUE_RENDER_QUALITY);
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,   RenderingHints.VALUE_ANTIALIAS_ON);
        if (icon == null)
        {
            // Defensive fallback if the resource fails to load — a dim grey dot
            // so the click target is still visible.
            g2.setColor(new Color(110, 110, 110));
            g2.fillOval(0, 0, size - 1, size - 1);
        }
        else
        {
            drawIconCentered(g2, icon, 0, 0, size);
        }
        g2.dispose();
    }

    /**
     * Scale the icon to fit within a {@code box × box} square, preserving
     * aspect ratio, and draw it centered at ({@code x},{@code y}).
     */
    private static void drawIconCentered(Graphics2D g2, BufferedImage img, int x, int y, int box)
    {
        int iw = img.getWidth();
        int ih = img.getHeight();
        if (iw <= 0 || ih <= 0)
        {
            return;
        }
        double s = Math.min((double) box / iw, (double) box / ih);
        int w = Math.max(1, (int) Math.round(iw * s));
        int h = Math.max(1, (int) Math.round(ih * s));
        int dx = x + (box - w) / 2;
        int dy = y + (box - h) / 2;
        g2.drawImage(img, dx, dy, w, h, null);
    }

    private void showPicker()
    {
        if (onChange == null)
        {
            return;
        }
        JPopupMenu menu = new JPopupMenu();
        menu.setBackground(Theme.BACKGROUND_DARKER);
        menu.setBorder(BorderFactory.createLineBorder(Theme.CARD_BORDER, 1));
        for (AccountType t : AccountType.values())
        {
            menu.add(createMenuItem(t));
        }
        menu.show(this, 0, getHeight());
    }

    private JMenuItem createMenuItem(AccountType t)
    {
        JMenuItem item = new JMenuItem(t.getDisplayName());
        item.setIcon(swatchIcon(t, 14));
        item.setIconTextGap(8);
        item.setBackground(Theme.BACKGROUND_DARKER);
        item.setForeground(Theme.TEXT_PRIMARY);
        item.setFont(Theme.fontRegular(item.getFont(), Theme.FONT_SIZE_SMALL));
        item.setBorder(new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM));
        if (t == type)
        {
            item.setForeground(Theme.ACCENT_ORANGE);
            item.setFont(Theme.fontBold(item.getFont(), Theme.FONT_SIZE_SMALL));
        }
        item.addActionListener(e ->
        {
            setType(t);
            onChange.accept(t);
        });
        return item;
    }

    /**
     * Reusable icon swatch matching the badge rendering. Used by dropdown
     * renderers (InlineAccountForm) and menu items so the picker UI is
     * self-describing.
     */
    public static Icon swatchIcon(AccountType t, int size)
    {
        return new Icon()
        {
            @Override
            public void paintIcon(Component c, Graphics g, int x, int y)
            {
                BufferedImage icon = iconFor(t);
                if (icon == null)
                {
                    return;
                }
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
                g2.setRenderingHint(RenderingHints.KEY_RENDERING,      RenderingHints.VALUE_RENDER_QUALITY);
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,   RenderingHints.VALUE_ANTIALIAS_ON);
                drawIconCentered(g2, icon, x, y, size);
                g2.dispose();
            }

            @Override
            public int getIconWidth() { return size; }

            @Override
            public int getIconHeight() { return size; }
        };
    }
}

package com.mylosis.roster.ui.components;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountType;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.ui.GroupComboItem;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.util.List;
import java.util.function.Consumer;

@Slf4j
public class InlineAccountForm extends JPanel
{
    private final RosterPlugin plugin;
    private final Account existingAccount;
    private final boolean showCategoryDropdown;
    private final String presetGroupId;

    private JTextField usernameField;
    private JTextField aliasField;
    private JTextField notesField;
    private JComboBox<GroupComboItem> categoryCombo;
    // Only present when creating a new account (existingAccount == null).
    // Editing existing accounts changes type via the card's clickable badge.
    private JComboBox<AccountType> typeCombo;

    @Setter
    private Consumer<Account> onSave;
    @Setter
    private Runnable onCancel;

    public InlineAccountForm(RosterPlugin plugin, Account existingAccount,
                             boolean showCategoryDropdown, String presetGroupId)
    {
        this.plugin = plugin;
        this.existingAccount = existingAccount;
        this.showCategoryDropdown = showCategoryDropdown;
        this.presetGroupId = presetGroupId;

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(Theme.FORM_BACKGROUND);
        setBorder(new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM));
        setAlignmentX(Component.LEFT_ALIGNMENT);

        buildForm();
        populateFields();
        setupKeyboardShortcuts();
    }

    private void buildForm()
    {
        // Username field (required)
        add(createFieldRow("Login *", usernameField = createTextField("Email or username")));
        add(Box.createVerticalStrut(Theme.SPACING_XS));

        // Alias field (optional)
        add(createFieldRow("Alias", aliasField = createTextField("Display name")));
        add(Box.createVerticalStrut(Theme.SPACING_XS));

        // Category dropdown (optional based on context)
        if (showCategoryDropdown)
        {
            categoryCombo = new JComboBox<>();
            categoryCombo.setBackground(Theme.BACKGROUND_DARKER);
            categoryCombo.setForeground(Theme.TEXT_PRIMARY);
            categoryCombo.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT));
            populateCategories();
            add(createFieldRow("Category", categoryCombo));
            add(Box.createVerticalStrut(Theme.SPACING_XS));
        }

        // Type dropdown — shown only when creating a new account.
        // For existing accounts the badge on the card is the change affordance.
        if (existingAccount == null)
        {
            typeCombo = new JComboBox<>(AccountType.values());
            typeCombo.setBackground(Theme.BACKGROUND_DARKER);
            typeCombo.setForeground(Theme.TEXT_PRIMARY);
            typeCombo.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT));
            typeCombo.setRenderer(new AccountTypeComboRenderer());
            typeCombo.setSelectedItem(AccountType.MAIN);
            add(createFieldRow("Type", typeCombo));
            add(Box.createVerticalStrut(Theme.SPACING_XS));
        }

        // Notes field (single line for compactness)
        add(createFieldRow("Notes", notesField = createTextField("Notes")));
        add(Box.createVerticalStrut(Theme.SPACING_SM));

        // Buttons
        add(createButtonPanel());
    }

    private JPanel createFieldRow(String labelText, JComponent field)
    {
        JPanel row = new JPanel(new BorderLayout(Theme.SPACING_XS, 0));
        row.setOpaque(false);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        JLabel label = new JLabel(labelText);
        label.setForeground(Theme.TEXT_SECONDARY);
        label.setFont(Theme.fontRegular(label.getFont(), Theme.FONT_SIZE_SMALL));
        label.setPreferredSize(new Dimension(55, Theme.BUTTON_HEIGHT));
        row.add(label, BorderLayout.WEST);
        row.add(field, BorderLayout.CENTER);
        return row;
    }

    private JTextField createTextField(String tooltip)
    {
        JTextField field = new JTextField();
        field.setBackground(Theme.BACKGROUND_DARKER);
        field.setForeground(Theme.TEXT_PRIMARY);
        field.setCaretColor(Theme.TEXT_PRIMARY);
        field.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(Theme.CARD_BORDER),
            new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM)));
        field.setFont(Theme.fontRegular(field.getFont(), Theme.FONT_SIZE_BODY));
        field.setToolTipText(tooltip);
        field.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT));
        return field;
    }

    private void populateCategories()
    {
        if (categoryCombo == null) return;
        categoryCombo.addItem(new GroupComboItem(null, "Uncategorized"));
        for (ProfileGroup group : plugin.getAccountStorage().getGroups())
            categoryCombo.addItem(new GroupComboItem(group.getId(), group.getName()));
    }

    private void selectCategory(String groupId)
    {
        if (categoryCombo == null) return;
        for (int i = 0; i < categoryCombo.getItemCount(); i++)
        {
            GroupComboItem item = categoryCombo.getItemAt(i);
            if ((groupId == null && item.id == null) || (groupId != null && groupId.equals(item.id)))
            { categoryCombo.setSelectedIndex(i); return; }
        }
    }

    private JPanel createButtonPanel()
    {
        JPanel panel = new JPanel(new GridLayout(1, 2, Theme.SPACING_XS, 0));
        panel.setOpaque(false);
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT_SM));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        JButton cancelButton = createButton("Cancel", Theme.BUTTON_SECONDARY, Theme.BUTTON_SECONDARY_HOVER);
        cancelButton.addActionListener(e -> doCancel());
        panel.add(cancelButton);
        JButton saveButton = createButton("Save", Theme.BUTTON_PRIMARY, Theme.BUTTON_PRIMARY_HOVER);
        saveButton.addActionListener(e -> doSave());
        panel.add(saveButton);
        return panel;
    }

    private JButton createButton(String text, Color background, Color hoverBackground)
    {
        JButton button = new JButton(text);
        button.setBackground(background);
        button.setForeground(Theme.TEXT_PRIMARY);
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setFont(Theme.fontRegular(button.getFont(), Theme.FONT_SIZE_HEADING));
        button.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override public void mouseEntered(java.awt.event.MouseEvent e) { button.setBackground(hoverBackground); }
            @Override public void mouseExited(java.awt.event.MouseEvent e) { button.setBackground(background); }
        });
        return button;
    }

    private void populateFields()
    {
        if (existingAccount != null)
        {
            usernameField.setText(existingAccount.getUsername());
            aliasField.setText(existingAccount.getAlias());
            AccountMetadata meta = existingAccount.getMetadata();
            if (meta != null && meta.getNotes() != null) notesField.setText(meta.getNotes());
            if (showCategoryDropdown) selectCategory(existingAccount.getGroupId());
        }
        else if (showCategoryDropdown && presetGroupId != null) selectCategory(presetGroupId);
    }

    private void setupKeyboardShortcuts()
    {
        getInputMap(WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(
            KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, KeyEvent.CTRL_DOWN_MASK), "save");
        getActionMap().put("save", new AbstractAction() {
            @Override public void actionPerformed(java.awt.event.ActionEvent e) { doSave(); }
        });

        getInputMap(WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(
            KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "cancel");
        getActionMap().put("cancel", new AbstractAction() {
            @Override public void actionPerformed(java.awt.event.ActionEvent e) { doCancel(); }
        });

        KeyAdapter enterAdapter = new KeyAdapter() {
            @Override public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_ENTER && !e.isControlDown()) {
                    e.consume();
                    // Component-local focus hop; the global focus-manager API is
                    // disallowed on the Plugin Hub (flagged in PR #13538).
                    e.getComponent().transferFocus();
                }
            }
        };
        usernameField.addKeyListener(enterAdapter);
        aliasField.addKeyListener(enterAdapter);
        notesField.addKeyListener(enterAdapter);
    }

    private void doSave()
    {
        String username = usernameField.getText().trim();
        if (!validateUsername(username)) return;

        Account profile = buildProfile(username);
        applyGroupId(profile);
        applyMetadata(profile);

        // Log the id only — username is the login email, and debug logs end up
        // in client.log files that users paste into bug reports.
        log.debug("Inline form saving profile: {}", profile.getId());

        if (onSave != null)
        {
            onSave.accept(profile);
        }
    }

    private boolean validateUsername(String username)
    {
        if (!username.isEmpty()) return true;

        usernameField.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(Theme.BUTTON_DANGER),
            new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM)
        ));
        usernameField.requestFocusInWindow();
        return false;
    }

    private Account buildProfile(String username)
    {
        String alias = aliasField.getText().trim();

        if (existingAccount != null)
        {
            existingAccount.setUsername(username);
            existingAccount.setAlias(alias.isEmpty() ? null : alias);
            return existingAccount;
        }
        return Account.createNew(alias.isEmpty() ? null : alias, username);
    }

    private void applyGroupId(Account profile)
    {
        if (showCategoryDropdown && categoryCombo != null)
        {
            GroupComboItem selected = (GroupComboItem) categoryCombo.getSelectedItem();
            profile.setGroupId(selected != null ? selected.id : null);
        }
        else if (presetGroupId != null)
        {
            profile.setGroupId(presetGroupId);
        }
    }

    private void applyMetadata(Account profile)
    {
        String notes = notesField.getText().trim();
        AccountMetadata meta = profile.getMetadata();
        if (meta == null)
        {
            meta = AccountMetadata.createDefault();
            profile.setMetadata(meta);
        }
        meta.setNotes(notes.isEmpty() ? null : notes);
        // Notes were mutated through the metadata object directly, which
        // bypasses Account's invalidating setters — drop the cached search
        // haystack or searching for the new notes text misses until the next
        // unrelated mutation. (saveAccount also invalidates, but not every
        // onSave consumer routes through it.)
        profile.invalidateSearchHaystack();
        // Type only flows through the form for new accounts; existing accounts
        // change type via the card badge popover.
        if (typeCombo != null)
        {
            AccountType selectedType = (AccountType) typeCombo.getSelectedItem();
            if (selectedType != null)
            {
                meta.setAccountType(selectedType);
            }
        }
    }

    private void doCancel()
    {
        if (onCancel != null) onCancel.run();
    }

    public void focusUsernameField()
    {
        SwingUtilities.invokeLater(() -> usernameField.requestFocusInWindow());
    }

    public void clearFields()
    {
        usernameField.setText("");
        aliasField.setText("");
        notesField.setText("");
        if (categoryCombo != null)
        {
            categoryCombo.setSelectedIndex(0);
        }
        if (typeCombo != null)
        {
            typeCombo.setSelectedItem(AccountType.MAIN);
        }
        // Reset username field border in case it was highlighted as error
        usernameField.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(Theme.CARD_BORDER),
            new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM)
        ));
    }

    /**
     * Renders each AccountType in the dropdown with its badge swatch alongside the label.
     * Mirrors the popover that opens when clicking a card badge, so the visual mapping
     * is the same in both places.
     */
    private static class AccountTypeComboRenderer extends DefaultListCellRenderer
    {
        @Override
        public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                                                      boolean isSelected, boolean cellHasFocus)
        {
            super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
            if (value instanceof AccountType)
            {
                AccountType t = (AccountType) value;
                setText(t.getDisplayName());
                setIcon(AccountTypeBadge.swatchIcon(t, 12));
                setIconTextGap(8);
                setBorder(new EmptyBorder(2, 4, 2, 4));
            }
            return this;
        }
    }
}

package com.mylosis.roster.ui.components;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;

import javax.swing.ImageIcon;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;

/**
 * Icon registry for the plugin. Provides access to icon resources with caching.
 */
@Slf4j
public final class Icons
{
    private Icons() {} // Prevent instantiation

    private static final String ICON_PATH = "/com/mylosis/roster/";
    private static final Map<String, ImageIcon> iconCache = new HashMap<>();

    // Icon names
    public static final String ADD = "add";
    public static final String EDIT = "edit";
    public static final String DELETE = "delete";
    public static final String EXPORT = "export";
    public static final String IMPORT = "import";
    public static final String CLIPBOARD = "clipboard";
    public static final String TRANSFER = "transfer";
    public static final String GROUP = "group";
    public static final String CATEGORY = "category";
    public static final String EXPAND = "expand";
    public static final String COLLAPSE = "collapse";
    public static final String MENU = "menu";
    public static final String SEARCH = "search";
    public static final String USER = "user";
    public static final String LOGIN = "login";
    public static final String GRID = "grid";
    public static final String LIST = "list";

    /**
     * Gets an icon by name. Returns a fallback if the icon is not found.
     */
    public static ImageIcon get(String name)
    {
        return get(name, Theme.ICON_SIZE);
    }

    /**
     * Gets an icon by name with a specific size.
     */
    public static ImageIcon get(String name, int size)
    {
        String cacheKey = name + "_" + size;
        if (iconCache.containsKey(cacheKey))
        {
            return iconCache.get(cacheKey);
        }

        ImageIcon icon = loadIcon(name, size);
        iconCache.put(cacheKey, icon);
        return icon;
    }

    private static ImageIcon loadIcon(String name, int size)
    {
        try
        {
            BufferedImage img = ImageUtil.loadImageResource(Icons.class, ICON_PATH + name + ".png");
            if (img.getWidth() != size || img.getHeight() != size)
            {
                img = ImageUtil.resizeImage(img, size, size);
            }
            return new ImageIcon(img);
        }
        catch (Exception e)
        {
            log.debug("Icon not found: {}, using fallback", name);
            return new ImageIcon(createFallbackIcon(name, size));
        }
    }

    /**
     * Creates a simple fallback icon when the actual icon is not found.
     * Delegates to specific draw methods per icon type.
     */
    private static BufferedImage createFallbackIcon(String name, int size)
    {
        BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        switch (name)
        {
            case ADD:
                drawAddIcon(g, size);
                break;
            case DELETE:
                drawDeleteIcon(g, size);
                break;
            case EXPAND:
                drawExpandIcon(g, size);
                break;
            case COLLAPSE:
                drawCollapseIcon(g, size);
                break;
            case MENU:
                drawMenuIcon(g, size);
                break;
            case USER:
                drawUserIcon(g, size);
                break;
            case GROUP:
            case CATEGORY:
                drawFolderIcon(g, size);
                break;
            case LOGIN:
                drawLoginIcon(g, size);
                break;
            case EDIT:
                drawEditIcon(g, size);
                break;
            case EXPORT:
            case IMPORT:
                drawExportImportIcon(g, size, EXPORT.equals(name));
                break;
            case CLIPBOARD:
                drawClipboardIcon(g, size);
                break;
            case TRANSFER:
                drawTransferIcon(g, size);
                break;
            case SEARCH:
                drawSearchIcon(g, size);
                break;
            case GRID:
                drawGridIcon(g, size);
                break;
            case LIST:
                drawListIcon(g, size);
                break;
            default:
                drawDefaultIcon(g, size);
                break;
        }

        g.dispose();
        return img;
    }

    private static void drawAddIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.BUTTON_PRIMARY);
        int center = size / 2;
        int barLength = (int) (size * 0.6);
        int barThickness = Math.max(2, size / 8);
        g.fillRect(center - barLength / 2, center - barThickness / 2, barLength, barThickness);
        g.fillRect(center - barThickness / 2, center - barLength / 2, barThickness, barLength);
    }

    private static void drawDeleteIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.BUTTON_DANGER);
        g.setStroke(new java.awt.BasicStroke(Math.max(2, size / 6f)));
        int margin = size / 4;
        g.drawLine(margin, margin, size - margin, size - margin);
        g.drawLine(size - margin, margin, margin, size - margin);
    }

    private static void drawExpandIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        int[] xPoints = {size / 3, size * 2 / 3, size / 3};
        int[] yPoints = {size / 4, size / 2, size * 3 / 4};
        g.fillPolygon(xPoints, yPoints, 3);
    }

    private static void drawCollapseIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        int[] xPoints = {size / 4, size / 2, size * 3 / 4};
        int[] yPoints = {size / 3, size * 2 / 3, size / 3};
        g.fillPolygon(xPoints, yPoints, 3);
    }

    private static void drawMenuIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        int dotSize = Math.max(3, size / 5);
        int dotX = size / 2 - dotSize / 2;
        g.fillOval(dotX, size / 4 - dotSize / 2, dotSize, dotSize);
        g.fillOval(dotX, size / 2 - dotSize / 2, dotSize, dotSize);
        g.fillOval(dotX, size * 3 / 4 - dotSize / 2, dotSize, dotSize);
    }

    private static void drawUserIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        int headRadius = size / 4;
        g.fillOval(size / 2 - headRadius, size / 6, headRadius * 2, headRadius * 2);
        g.fillArc(size / 6, size / 2, size * 2 / 3, size * 2 / 3, 0, 180);
    }

    private static void drawFolderIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        int folderMargin = size / 6;
        int folderWidth = size - folderMargin * 2;
        int folderHeight = (int) (folderWidth * 0.7);
        int tabWidth = folderWidth / 3;
        int tabHeight = folderHeight / 5;
        g.fillRoundRect(folderMargin, folderMargin + tabHeight, tabWidth, tabHeight, 2, 2);
        g.fillRoundRect(folderMargin, folderMargin + tabHeight * 2, folderWidth, folderHeight, 3, 3);
    }

    private static void drawLoginIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.BUTTON_PRIMARY);
        g.setStroke(new java.awt.BasicStroke(Math.max(2, size / 8f)));
        int arrowY = size / 2;
        g.drawLine(size / 4, arrowY, size * 3 / 4, arrowY);
        g.drawLine(size / 2, size / 4, size * 3 / 4, arrowY);
        g.drawLine(size / 2, size * 3 / 4, size * 3 / 4, arrowY);
    }

    private static void drawEditIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        g.setStroke(new java.awt.BasicStroke(Math.max(1, size / 8f)));
        g.drawLine(size / 4, size * 3 / 4, size * 3 / 4, size / 4);
        g.drawLine(size / 4 - 2, size * 3 / 4 + 2, size / 4 + 2, size * 3 / 4 - 2);
    }

    private static void drawExportImportIcon(Graphics2D g, int size, boolean isExport)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        g.setStroke(new java.awt.BasicStroke(Math.max(2, size / 8f)));
        int arrowStart = isExport ? size * 2 / 3 : size / 3;
        int arrowEnd = isExport ? size / 3 : size * 2 / 3;
        g.drawLine(size / 2, arrowStart, size / 2, arrowEnd);
        int tipY = arrowEnd;
        int tipDir = isExport ? 1 : -1;
        g.drawLine(size / 3, tipY + tipDir * size / 6, size / 2, tipY);
        g.drawLine(size * 2 / 3, tipY + tipDir * size / 6, size / 2, tipY);
    }

    private static void drawClipboardIcon(Graphics2D g, int size)
    {
        Color iconColor = Theme.TEXT_SECONDARY;
        g.setColor(iconColor);
        int clipMargin = size / 5;
        int clipWidth = size - clipMargin * 2;
        int clipHeight = (int) (size * 0.75);
        g.fillRoundRect(clipMargin, size / 4, clipWidth, clipHeight, 3, 3);
        g.setColor(Theme.BACKGROUND);
        int clipTopWidth = clipWidth / 2;
        g.fillRoundRect(size / 2 - clipTopWidth / 2, size / 6, clipTopWidth, size / 5, 2, 2);
        g.setColor(iconColor);
        g.drawRoundRect(size / 2 - clipTopWidth / 2, size / 6, clipTopWidth, size / 5, 2, 2);
    }

    private static void drawTransferIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        g.setStroke(new java.awt.BasicStroke(Math.max(2, size / 8f)));
        int leftX = size / 3;
        g.drawLine(leftX, size * 2 / 3, leftX, size / 4);
        g.drawLine(leftX - size / 8, size / 4 + size / 6, leftX, size / 4);
        g.drawLine(leftX + size / 8, size / 4 + size / 6, leftX, size / 4);
        int rightX = size * 2 / 3;
        g.drawLine(rightX, size / 3, rightX, size * 3 / 4);
        g.drawLine(rightX - size / 8, size * 3 / 4 - size / 6, rightX, size * 3 / 4);
        g.drawLine(rightX + size / 8, size * 3 / 4 - size / 6, rightX, size * 3 / 4);
    }

    private static void drawSearchIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        g.setStroke(new java.awt.BasicStroke(Math.max(2, size / 8f)));
        int circleSize = size / 2;
        g.drawOval(size / 6, size / 6, circleSize, circleSize);
        g.drawLine(size / 6 + circleSize - 2, size / 6 + circleSize - 2, size * 5 / 6, size * 5 / 6);
    }

    private static void drawGridIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        int gs = (size - 6) / 2;
        int gap = 2;
        int off = 2;
        g.fillRect(off, off, gs, gs);
        g.fillRect(off + gs + gap, off, gs, gs);
        g.fillRect(off, off + gs + gap, gs, gs);
        g.fillRect(off + gs + gap, off + gs + gap, gs, gs);
    }

    private static void drawListIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        g.setStroke(new java.awt.BasicStroke(Math.max(2, size / 6f)));
        int lm = size / 5;
        g.drawLine(lm, size / 4, size - lm, size / 4);
        g.drawLine(lm, size / 2, size - lm, size / 2);
        g.drawLine(lm, size * 3 / 4, size - lm, size * 3 / 4);
    }

    private static void drawDefaultIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        g.fillOval(2, 2, size - 4, size - 4);
    }

    /**
     * Clears the icon cache. Useful when reloading resources.
     */
    public static void clearCache()
    {
        iconCache.clear();
    }
}

package com.mylosis.roster.ui.components;

import javax.swing.BorderFactory;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;

/**
 * A styled search bar component with live filtering support.
 */
public class SearchBar extends JPanel
{
    private final JTextField textField;
    private final JPanel clearButton;
    private Consumer<String> onSearchChanged;
    private boolean isFocused = false;
    private boolean clearHovered = false;
    private String placeholderText = "";

    /**
     * Debounce coalesces rapid keystrokes into a single search invocation.
     * Each typed character triggers a full panel rebuild downstream, so without
     * this a 10-character query meant 10 teardown-and-rebuild cycles. 120ms is
     * imperceptible to users but eliminates the burst — restart()-on-edit means
     * we only fire once the user actually pauses.
     */
    private static final int SEARCH_DEBOUNCE_MS = 120;
    private final Timer searchDebounceTimer;

    public SearchBar()
    {
        searchDebounceTimer = new Timer(SEARCH_DEBOUNCE_MS, e -> fireSearchChanged());
        searchDebounceTimer.setRepeats(false);

        setLayout(new BorderLayout(Theme.SPACING_SM, 0));
        setBackground(Theme.BACKGROUND_DARKER);
        setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(Theme.CARD_BORDER, 1),
            new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_SM)
        ));

        // Search icon
        JPanel iconPanel = new JPanel()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                super.paintComponent(g);
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(Theme.TEXT_MUTED);

                // Draw search icon (magnifying glass)
                int size = 12;
                int x = (getWidth() - size) / 2;
                int y = (getHeight() - size) / 2;
                g2.setStroke(new java.awt.BasicStroke(1.5f));
                g2.drawOval(x, y, size - 4, size - 4);
                g2.drawLine(x + size - 5, y + size - 5, x + size - 1, y + size - 1);
                g2.dispose();
            }
        };
        iconPanel.setOpaque(false);
        iconPanel.setPreferredSize(new Dimension(20, 20));
        add(iconPanel, BorderLayout.WEST);

        // Text field with placeholder painting
        textField = new JTextField()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                super.paintComponent(g);
                if (getText().isEmpty() && !isFocused && !placeholderText.isEmpty())
                {
                    Graphics2D g2 = (Graphics2D) g.create();
                    g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                    g2.setColor(Theme.TEXT_MUTED);
                    g2.setFont(getFont());
                    int y = (getHeight() + g2.getFontMetrics().getAscent() - g2.getFontMetrics().getDescent()) / 2;
                    g2.drawString(placeholderText, getInsets().left, y);
                    g2.dispose();
                }
            }
        };
        textField.setBorder(null);
        textField.setBackground(Theme.BACKGROUND_DARKER);
        textField.setForeground(Theme.TEXT_PRIMARY);
        textField.setCaretColor(Theme.TEXT_PRIMARY);
        textField.setOpaque(false);

        textField.getDocument().addDocumentListener(new DocumentListener()
        {
            @Override
            public void insertUpdate(DocumentEvent e)
            {
                notifySearchChanged();
            }

            @Override
            public void removeUpdate(DocumentEvent e)
            {
                notifySearchChanged();
            }

            @Override
            public void changedUpdate(DocumentEvent e)
            {
                notifySearchChanged();
            }
        });

        textField.addFocusListener(new FocusAdapter()
        {
            @Override
            public void focusGained(FocusEvent e)
            {
                isFocused = true;
                updateBorder();
                textField.repaint();
            }

            @Override
            public void focusLost(FocusEvent e)
            {
                isFocused = false;
                updateBorder();
                textField.repaint();
            }
        });

        add(textField, BorderLayout.CENTER);

        // Clear button
        clearButton = new JPanel()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                super.paintComponent(g);
                if (textField.getText().isEmpty())
                {
                    return;
                }

                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

                // Non-opaque component: Swing skips the automatic background
                // fill, so setBackground() from the hover listener never showed.
                // Paint the hover state ourselves.
                if (clearHovered)
                {
                    g2.setColor(Theme.BACKGROUND_HOVER);
                    g2.fillRoundRect(0, 0, getWidth(), getHeight(), 6, 6);
                }
                g2.setColor(Theme.TEXT_MUTED);

                // Draw refresh/circular arrow icon
                int size = 12;
                int x = (getWidth() - size) / 2;
                int y = (getHeight() - size) / 2;
                g2.setStroke(new java.awt.BasicStroke(1.5f));

                // Draw arc (270 degrees, leaving gap for arrow)
                g2.drawArc(x, y, size, size, 45, 270);

                // Draw arrowhead at the end of arc
                int arrowSize = 3;
                int arrowX = x + size - 1;
                int arrowY = y + size / 2 - 2;
                g2.drawLine(arrowX, arrowY, arrowX + arrowSize, arrowY - arrowSize);
                g2.drawLine(arrowX, arrowY, arrowX + arrowSize, arrowY + arrowSize);

                g2.dispose();
            }
        };
        clearButton.setOpaque(false);
        clearButton.setPreferredSize(new Dimension(20, 20));
        clearButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        clearButton.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                clear();
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                clearHovered = true;
                clearButton.repaint();
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                clearHovered = false;
                clearButton.repaint();
            }
        });
        add(clearButton, BorderLayout.EAST);

        setPreferredSize(new Dimension(0, 32));
    }

    private void updateBorder()
    {
        Color borderColor = isFocused ? Theme.ACCENT_BLUE : Theme.CARD_BORDER;
        setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(borderColor, 1),
            new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_SM)
        ));
        repaint();
    }

    private void notifySearchChanged()
    {
        clearButton.repaint();
        // Coalesce: each keystroke restarts the timer; the callback fires only
        // after the user pauses for SEARCH_DEBOUNCE_MS. Clearing the field via
        // clear() needs an immediate fire (no pause), handled in clear().
        searchDebounceTimer.restart();
    }

    private void fireSearchChanged()
    {
        if (onSearchChanged != null)
        {
            onSearchChanged.accept(textField.getText().toLowerCase().trim());
        }
    }

    public void setOnSearchChanged(Consumer<String> callback)
    {
        this.onSearchChanged = callback;
    }

    public String getText()
    {
        return textField.getText();
    }

    public void setText(String text)
    {
        textField.setText(text);
    }

    public void clear()
    {
        textField.setText("");
        textField.requestFocus();
        // Clear is an explicit user action — flush any pending debounce so the
        // filtered list updates immediately rather than after a brief delay.
        if (searchDebounceTimer.isRunning())
        {
            searchDebounceTimer.stop();
        }
        fireSearchChanged();
    }

    public void setPlaceholder(String placeholder)
    {
        this.placeholderText = placeholder != null ? placeholder : "";
        textField.setToolTipText(placeholder);
        textField.repaint();
    }
}

package com.mylosis.roster.ui.components;

import net.runelite.client.ui.ColorScheme;

import java.awt.Color;
import java.awt.Font;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Centralized theme constants for consistent UI styling throughout the plugin.
 */
public final class Theme
{
    private Theme() {} // Prevent instantiation

    /** Plugin version string displayed in the UI header. */
    public static final String VERSION = "1.1";

    // Base colors
    public static final Color BACKGROUND = ColorScheme.DARK_GRAY_COLOR;
    public static final Color BACKGROUND_DARKER = ColorScheme.DARKER_GRAY_COLOR;
    public static final Color BACKGROUND_HOVER = ColorScheme.DARK_GRAY_HOVER_COLOR;

    // Card colors
